def _new_stream_monitoring_records(
    stream_id: str,
    *,
    created_at: datetime | None = None,
) -> tuple[StreamMonitoringPolicyModel, StreamRuntimeCheckpointModel]:
    """Create inert continuity records; every new Stream starts explicitly off."""

    timestamp = created_at or datetime.now(UTC)
    return (
        StreamMonitoringPolicyModel(
            stream_id=stream_id,
            mode=StreamMonitoringMode.off.value,
            auto_create_review_candidates=False,
            evaluation_interval_seconds=DEFAULT_STREAM_MONITORING_INTERVAL_SECONDS,
            quiet_period_seconds=DEFAULT_STREAM_MONITORING_QUIET_SECONDS,
            minimum_detection_count=DEFAULT_STREAM_MONITORING_MINIMUM_DETECTIONS,
            policy_revision=1,
            armed_at=None,
            paused_at=None,
            updated_at=timestamp,
            pause_reason=None,
        ),
        StreamRuntimeCheckpointModel(
            stream_id=stream_id,
            observed_policy_revision=1,
            actual_state=StreamRuntimeState.stopped.value,
            app_instance_id=None,
            runtime_generation_id=None,
            last_start_attempt_at=None,
            last_healthy_frame_at=None,
            last_clean_stop_at=None,
            last_failure_at=None,
            failure_code=None,
            consecutive_failure_count=0,
            next_retry_at=None,
            last_stop_reason="policy_off",
            start_count=0,
            failure_count=0,
            evidence_handoff_count=0,
            safety_hold_active=False,
            updated_at=timestamp,
        ),
    )


def _stream_monitoring_policy_from_model(
    stream: StreamModel,
    model: StreamMonitoringPolicyModel,
) -> StreamMonitoringPolicyResponse:
    return StreamMonitoringPolicyResponse(
        stream_id=stream.id,
        source_id=stream.source_id,
        mode=StreamMonitoringMode(model.mode),
        auto_create_review_candidates=model.auto_create_review_candidates,
        evaluation_interval_seconds=model.evaluation_interval_seconds,
        quiet_period_seconds=model.quiet_period_seconds,
        minimum_detection_count=model.minimum_detection_count,
        policy_revision=model.policy_revision,
        armed_at=model.armed_at,
        paused_at=model.paused_at,
        updated_at=model.updated_at,
        pause_reason=model.pause_reason,
        persisted=True,
        message=(
            "Monitoring is disabled. Enable it explicitly from Stream Detail when this camera is ready."
            if model.mode == StreamMonitoringMode.off.value
            else "Monitoring is enabled and will be restored by the local supervisor."
            if model.mode == StreamMonitoringMode.armed.value
            else "Monitoring is paused and will not start until it is enabled again."
        ),
    )


def _camera_setup_source_kind(provider_key: str) -> SourceKind:
    return {
        "manual_media": SourceKind.manual_upload,
        "external_url": SourceKind.rtsp,
        "local_usb": SourceKind.local_camera,
        "folder_import_future": SourceKind.local_folder,
        "webhook_future": SourceKind.webhook,
        "camera_node": SourceKind.integration,
    }.get(provider_key, SourceKind.integration)


def _validate_camera_setup_urls(provider_key: str, config: dict[str, str]) -> None:
    """Reject malformed setup URLs before they reach persisted provider metadata."""

    keys = ("url", "live_stream_url") if provider_key == "external_url" else ()
    for key in keys:
        value = (config.get(key) or "").strip()
        if not value:
            continue
        parsed = urlsplit(value)
        allowed_schemes = {"http", "https", "rtsp"} if key == "live_stream_url" else {"http", "https"}
        if parsed.scheme.lower() not in allowed_schemes or not parsed.hostname:
            raise ValueError("camera_setup_invalid_url")
    if provider_key == "camera_node":
        address = (config.get("node_base_address") or "").strip()
        if address:
            try:
                normalize_camera_node_address(address)
            except CameraNodeClientError as error:
                raise ValueError("camera_setup_invalid_node_address") from error


class ProductRepository:
    """Persist product-level stream, zone, event, review, and export state.

    Source adapters will normalize activity into these tables later; they do not
    define the core product model.
    """

    def __init__(
        self,
        db_url: str | None = None,
        engine: Engine | None = None,
        media_root: str | Path | None = None,
        classifier_manifest_export_root: str | Path | None = None,
    ) -> None:
        self.db_url = resolve_database_url(db_url)
        self.media_root = resolve_media_root(media_root)
        self.classifier_manifest_export_root = Path(
            classifier_manifest_export_root or DEFAULT_CLASSIFIER_MANIFEST_EXPORT_ROOT
        )
        self.engine = engine or create_database_engine(self.db_url)
        self.schema_status = initialize_database(self.engine)
        self.session_factory = create_session_factory(self.engine)
        self._storage_retention_lock = threading.Lock()
        # A local model runner is bounded and request-bound. Keep a second request
        # for the same Visit from producing duplicate evidence while it is active.
        self._review_identification_assistant_lock = threading.Lock()
        self.seed_if_empty()

    def close(self) -> None:
        """Release pooled database handles before local data is replaced."""

        self.engine.dispose()

    def seed_if_empty(self) -> None:
        with self.session_factory() as session:
            with session.begin():
                self._seed_taxonomy_labels(session)
                source_count = session.scalar(select(func.count(CameraSourceModel.id))) or 0
                if source_count > 0:
                    return
                self._seed_session(session)

    def reset_demo_data(self) -> LocalDataStatus:
        # Reset only the sample walkthrough graph. Real cameras and their local
        # observations must survive a demo reset now that both can coexist.
        with self.session_factory() as session:
            with session.begin():
                graph = self._sample_graph_ids(session)
                self._delete_sample_graph(session, graph)
                self._seed_taxonomy_labels(session)
                self._seed_session(session)
            return self._local_data_status(session)

    def remove_sample_data(self, *, confirm: bool) -> SampleDataRemovalResponse:
        """Remove only the seeded walkthrough after a real Source exists.

        Added sample-linked captures, evidence, or corrections block removal so
        an action labeled "sample data" cannot silently discard user work.
        """

        if not confirm:
            raise ValueError("sample_data_confirmation_required")

        with self.session_factory() as session:
            with session.begin():
                real_source_count = session.scalar(
                    select(func.count(CameraSourceModel.id)).where(
                        CameraSourceModel.id != demo_data.SOURCE_ID
                    )
                ) or 0
                if real_source_count == 0:
                    raise ValueError("sample_data_requires_real_source")

                if session.get(CameraSourceModel, demo_data.SOURCE_ID) is None:
                    status = self._local_data_status(session)
                    return SampleDataRemovalResponse(
                        removed=False,
                        removed_counts={},
                        preserved_source_count=status.source_count,
                        status=status,
                        message="Sample walkthrough data is already removed.",
                    )

                graph = self._sample_graph_ids(session)
                if self._sample_graph_has_user_content(session, graph):
                    raise ValueError("sample_data_has_user_content")

                removed_counts = self._delete_sample_graph(session, graph)
                session.flush()
                status = self._local_data_status(session)
                return SampleDataRemovalResponse(
                    removed=True,
                    removed_counts=removed_counts,
                    preserved_source_count=status.source_count,
                    status=status,
                    message=(
                        "Sample walkthrough removed. Real cameras, observations, "
                        "corrections, exports, and local media were preserved."
                    ),
                )

    def _sample_graph_ids(self, session: Session) -> dict[str, set[str]]:
        """Collect records owned by the seeded demo Source without touching real Sources."""

        def ids_for(model: type, *criteria: Any) -> set[str]:
            statement = select(model.id)
            if criteria:
                statement = statement.where(*criteria)
            return set(session.scalars(statement).all())

        (
            _seed_sources,
            seed_streams,
            seed_zones,
            seed_events,
            seed_visits,
            seed_review_labels,
            seed_exports,
        ) = demo_data.seed_product_data()
        seed_export_ids = {item.id for item in seed_exports}

        source_ids = (
            {demo_data.SOURCE_ID}
            if session.get(CameraSourceModel, demo_data.SOURCE_ID) is not None
            else set()
        )
        stream_ids = ids_for(StreamModel, StreamModel.source_id == demo_data.SOURCE_ID)
        zone_ids = ids_for(ZoneModel, ZoneModel.stream_id.in_(stream_ids))
        event_ids = ids_for(EventModel, EventModel.stream_id.in_(stream_ids))
        visit_ids = ids_for(VisitModel, VisitModel.event_id.in_(event_ids))
        media_asset_ids = ids_for(
            MediaAssetModel,
            or_(
                MediaAssetModel.source_id == demo_data.SOURCE_ID,
                MediaAssetModel.stream_id.in_(stream_ids),
            ),
        )
        motion_evidence_ids = ids_for(
            MotionEvidenceModel,
            or_(
                MotionEvidenceModel.source_id == demo_data.SOURCE_ID,
                MotionEvidenceModel.stream_id.in_(stream_ids),
                MotionEvidenceModel.zone_id.in_(zone_ids),
                MotionEvidenceModel.snapshot_media_asset_id.in_(media_asset_ids),
            ),
        )
        detection_run_ids = ids_for(
            DetectionRunModel,
            DetectionRunModel.media_asset_id.in_(media_asset_ids),
        )
        detection_proposal_ids = ids_for(
            DetectionProposalModel,
            or_(
                DetectionProposalModel.run_id.in_(detection_run_ids),
                DetectionProposalModel.media_asset_id.in_(media_asset_ids),
                DetectionProposalModel.stream_id.in_(stream_ids),
                DetectionProposalModel.zone_id.in_(zone_ids),
                DetectionProposalModel.event_id.in_(event_ids),
                DetectionProposalModel.visit_id.in_(visit_ids),
            ),
        )
        species_suggestion_ids = ids_for(
            SpeciesSuggestionModel,
            or_(
                SpeciesSuggestionModel.source_id == demo_data.SOURCE_ID,
                SpeciesSuggestionModel.stream_id.in_(stream_ids),
                SpeciesSuggestionModel.event_id.in_(event_ids),
                SpeciesSuggestionModel.visit_id.in_(visit_ids),
                SpeciesSuggestionModel.media_asset_id.in_(media_asset_ids),
                SpeciesSuggestionModel.motion_evidence_id.in_(motion_evidence_ids),
            ),
        )
        bioclip_attempt_ids = ids_for(
            BioClipIdentificationAttemptModel,
            or_(
                BioClipIdentificationAttemptModel.source_id == demo_data.SOURCE_ID,
                BioClipIdentificationAttemptModel.stream_id.in_(stream_ids),
                BioClipIdentificationAttemptModel.zone_id.in_(zone_ids),
                BioClipIdentificationAttemptModel.event_id.in_(event_ids),
                BioClipIdentificationAttemptModel.visit_id.in_(visit_ids),
                BioClipIdentificationAttemptModel.media_asset_id.in_(media_asset_ids),
                BioClipIdentificationAttemptModel.motion_evidence_id.in_(
                    motion_evidence_ids
                ),
                BioClipIdentificationAttemptModel.detection_proposal_id.in_(
                    detection_proposal_ids
                ),
                BioClipIdentificationAttemptModel.resulting_species_suggestion_id.in_(
                    species_suggestion_ids
                ),
            ),
        )
        detection_ids = ids_for(
            DetectionModel,
            or_(
                DetectionModel.event_id.in_(event_ids),
                DetectionModel.zone_id.in_(zone_ids),
            ),
        )
        review_label_ids = ids_for(
            ReviewLabelModel,
            or_(
                and_(
                    ReviewLabelModel.target_type == "event",
                    ReviewLabelModel.target_id.in_(event_ids),
                ),
                and_(
                    ReviewLabelModel.target_type == "visit",
                    ReviewLabelModel.target_id.in_(visit_ids),
                ),
            ),
        )
        dataset_export_ids = ids_for(
            DatasetExportModel,
            DatasetExportModel.id.in_(seed_export_ids),
        )
        provider_configuration_ids = (
            {demo_data.SOURCE_ID}
            if session.get(SourceProviderConfigurationModel, demo_data.SOURCE_ID) is not None
            else set()
        )

        return {
            "sources": source_ids,
            "streams": stream_ids,
            "zones": zone_ids,
            "events": event_ids,
            "visits": visit_ids,
            "media_assets": media_asset_ids,
            "motion_evidence": motion_evidence_ids,
            "detection_runs": detection_run_ids,
            "detection_proposals": detection_proposal_ids,
            "species_suggestions": species_suggestion_ids,
            "bioclip_attempts": bioclip_attempt_ids,
            "detections": detection_ids,
            "review_labels": review_label_ids,
            "dataset_exports": dataset_export_ids,
            "provider_configurations": provider_configuration_ids,
            "seed_streams": {item.id for item in seed_streams},
            "seed_zones": {item.id for item in seed_zones},
            "seed_events": {item.id for item in seed_events},
            "seed_visits": {item.id for item in seed_visits},
            "seed_detections": {
                detection.id for event in seed_events for detection in event.detections
            },
            "seed_review_labels": {item.id for item in seed_review_labels},
        }

    def _sample_graph_has_user_content(
        self,
        session: Session,
        graph: dict[str, set[str]],
    ) -> bool:
        if graph["streams"] - graph["seed_streams"]:
            return True
        if graph["zones"] - graph["seed_zones"]:
            return True
        if graph["events"] - graph["seed_events"]:
            return True
        if graph["visits"] - graph["seed_visits"]:
            return True
        if graph["detections"] - graph["seed_detections"]:
            return True
        if graph["review_labels"] - graph["seed_review_labels"]:
            return True
        if any(
            graph[key]
            for key in (
                "media_assets",
                "motion_evidence",
                "detection_runs",
                "detection_proposals",
                "species_suggestions",
                "bioclip_attempts",
            )
        ):
            return True

        configuration = session.get(SourceProviderConfigurationModel, demo_data.SOURCE_ID)
        return configuration is not None and configuration.provider_key != "demo"

    def _delete_sample_graph(
        self,
        session: Session,
        graph: dict[str, set[str]],
    ) -> dict[str, int]:
        """Delete the collected demo graph in dependency order; media files remain local."""

        def delete_ids(model: type, ids: set[str]) -> None:
            if ids:
                session.execute(delete(model).where(model.id.in_(ids)))

        delete_ids(
            BioClipIdentificationAttemptModel,
            graph["bioclip_attempts"],
        )
        delete_ids(SpeciesSuggestionModel, graph["species_suggestions"])
        delete_ids(DetectionProposalModel, graph["detection_proposals"])
        delete_ids(DetectionRunModel, graph["detection_runs"])
        delete_ids(MotionEvidenceModel, graph["motion_evidence"])
        delete_ids(DetectionModel, graph["detections"])
        delete_ids(ReviewLabelModel, graph["review_labels"])
        delete_ids(VisitModel, graph["visits"])
        delete_ids(EventModel, graph["events"])
        delete_ids(ZoneModel, graph["zones"])
        delete_ids(MediaAssetModel, graph["media_assets"])
        delete_ids(DatasetExportModel, graph["dataset_exports"])
        if graph["provider_configurations"]:
            session.execute(
                delete(SourceProviderConfigurationModel).where(
                    SourceProviderConfigurationModel.source_id.in_(
                        graph["provider_configurations"]
                    )
                )
            )
        if graph["streams"]:
            session.execute(
                delete(StreamRuntimeCheckpointModel).where(
                    StreamRuntimeCheckpointModel.stream_id.in_(graph["streams"])
                )
            )
            session.execute(
                delete(StreamMonitoringPolicyModel).where(
                    StreamMonitoringPolicyModel.stream_id.in_(graph["streams"])
                )
            )
        delete_ids(StreamModel, graph["streams"])
        delete_ids(CameraSourceModel, graph["sources"])

        return {
            key: len(value)
            for key, value in graph.items()
            if not key.startswith("seed_") and value
        }

    def local_data_status(self) -> LocalDataStatus:
        with self.session_factory() as session:
            return self._local_data_status(session)

    def get_worker_status(self) -> WorkerStatusResponse:
        workers = list_worker_status_items()
        summary = WorkerStatusSummary(
            total_workers=len(workers),
            implemented_workers=sum(worker.implemented for worker in workers),
            enabled_workers=sum(worker.enabled for worker in workers),
            running_workers=sum(worker.state == "running" for worker in workers),
            failed_workers=sum(worker.state == "failed" for worker in workers),
            truth_creating_workers=sum(worker.can_create_truth for worker in workers),
            warnings=[
                "Worker status is read-only placeholder data; no worker runtime exists yet."
            ],
        )
        return WorkerStatusResponse(
            workers=workers,
            summary=summary,
            generated_at=datetime.now(UTC),
            read_only=True,
        )

    def get_external_url_worker_dry_run_plan(self) -> ExternalUrlWorkerDryRunResponse:
        with self.session_factory() as session:
            items: list[ExternalUrlWorkerDryRunItem] = []
            sources = session.scalars(select(CameraSourceModel).order_by(CameraSourceModel.id)).all()
            for source in sources:
                model = session.get(SourceProviderConfigurationModel, source.id)
                stream_ids = self._stream_ids_for_source(session, source.id)
                configuration = _source_provider_configuration_from_model(
                    source,
                    model,
                    stream_ids,
                )
                if configuration.provider_key != "external_url":
                    continue

                has_url_configuration = (
                    "url" in configuration.configured_fields
                    and "url" not in configuration.missing_fields
                )
                reasons = [
                    (
                        "external_url provider configured"
                        if has_url_configuration
                        else "missing external URL configuration"
                    ),
                    "future scheduler disabled",
                    "dry run only; no fetch performed",
                ]
                items.append(
                    ExternalUrlWorkerDryRunItem(
                        source_id=source.id,
                        source_name=source.name,
                        provider_key=configuration.provider_key,
                        worker_key=EXTERNAL_URL_PREVIEW_WORKER_KEY,
                        eligible=has_url_configuration,
                        state="disabled",
                        would_fetch=False,
                        would_create_media_asset=False,
                        would_create_motion_evidence=False,
                        would_create_event=False,
                        would_create_visit=False,
                        would_create_review_label=False,
                        would_create_truth=False,
                        reasons=reasons,
                        warnings=["Worker runtime is not implemented in this phase."],
                    )
                )

        eligible_sources = sum(item.eligible for item in items)
        summary = ExternalUrlWorkerDryRunSummary(
            total_sources_considered=len(items),
            eligible_sources=eligible_sources,
            ineligible_sources=len(items) - eligible_sources,
            would_fetch_count=sum(item.would_fetch for item in items),
            would_create_media_asset_count=sum(item.would_create_media_asset for item in items),
            would_create_motion_evidence_count=sum(
                item.would_create_motion_evidence for item in items
            ),
            would_create_truth_count=sum(item.would_create_truth for item in items),
            warnings=["Dry run only; no external URL fetch performed."],
        )
        return ExternalUrlWorkerDryRunResponse(
            worker_key=EXTERNAL_URL_PREVIEW_WORKER_KEY,
            provider_key="external_url",
            read_only=True,
            dry_run=True,
            generated_at=datetime.now(UTC),
            items=items,
            summary=summary,
        )

    def _seed_session(self, session: Session) -> None:
        (
            sources,
            streams,
            zones,
            events,
            visits,
            review_labels,
            dataset_exports,
        ) = demo_data.seed_product_data()

        session.add_all(
            [
                CameraSourceModel(
                    id=source.id,
                    name=source.name,
                    kind=source.kind.value,
                    status=source.status.value,
                    description=source.description,
                )
                for source in sources
            ]
        )
        session.add_all(
            [
                StreamModel(
                    id=stream.id,
                    source_id=stream.source_id,
                    name=stream.name,
                    description=stream.description,
                    is_live=stream.is_live,
                )
                for stream in streams
            ]
        )
        for stream in streams:
            session.add_all(_new_stream_monitoring_records(stream.id))
        session.add_all(
            [
                ZoneModel(
                    id=zone.id,
                    stream_id=zone.stream_id,
                    name=zone.name,
                    zone_type=zone.zone_type.value,
                    polygon_json=_points_to_json(zone.polygon),
                    is_active=zone.is_active,
                )
                for zone in zones
            ]
        )
        session.add_all(
            [
                EventModel(
                    id=event.id,
                    stream_id=event.stream_id,
                    title=event.title,
                    event_type=event.event_type,
                    started_at=event.started_at,
                    ended_at=event.ended_at,
                    primary_zone_id=event.primary_zone_id,
                    review_status=event.review_status.value,
                )
                for event in events
            ]
        )
        session.add_all(
            [
                DetectionModel(
                    id=detection.id,
                    event_id=event.id,
                    label=detection.label,
                    confidence=detection.confidence,
                    zone_id=detection.zone_id,
                    bbox_json=_bbox_to_json(detection.bbox),
                )
                for event in events
                for detection in event.detections
            ]
        )
        session.add_all(
            [
                VisitModel(
                    id=visit.id,
                    event_id=visit.event_id,
                    subject_label=visit.subject_label,
                    species_guess=visit.species_guess,
                    confidence=visit.confidence,
                    reviewed_label=visit.reviewed_label,
                    review_status=visit.review_status.value,
                    representative_media_path=visit.representative_media_path,
                )
                for visit in visits
            ]
        )
        session.add_all(
            [
                ReviewLabelModel(
                    id=label.id,
                    target_type=label.target_type,
                    target_id=label.target_id,
                    label=label.label,
                    notes=label.notes,
                    created_at=label.created_at,
                )
                for label in review_labels
            ]
        )
        session.add_all(
            [
                DatasetExportModel(
                    id=dataset_export.id,
                    name=dataset_export.name,
                    status=dataset_export.status.value,
                    reviewed_only=dataset_export.reviewed_only,
                    include_detections=dataset_export.include_detections,
                    include_zone_context=dataset_export.include_zone_context,
                    record_count=dataset_export.record_count,
                    created_at=dataset_export.created_at,
                )
                for dataset_export in dataset_exports
            ]
        )

    def _seed_taxonomy_labels(self, session: Session) -> None:
        # Taxonomy prepares future classifiers while keeping user corrections as truth.
        for label in demo_data.seed_taxonomy_labels():
            existing = session.get(TaxonomyLabelModel, label.id)
            if existing is None:
                session.add(
                    TaxonomyLabelModel(
                        id=label.id,
                        label=label.label,
                        display_name=label.display_name,
                        category=label.category.value,
                        scientific_name=label.scientific_name,
                        aliases_json=json.dumps(label.aliases),
                        is_species=label.is_species,
                        is_reviewable=label.is_reviewable,
                        sort_order=label.sort_order,
                    )
                )
                continue

            existing.label = label.label
            existing.display_name = label.display_name
            existing.category = label.category.value
            existing.scientific_name = label.scientific_name
            existing.aliases_json = json.dumps(label.aliases)
            existing.is_species = label.is_species
            existing.is_reviewable = label.is_reviewable
            existing.sort_order = label.sort_order

    def _local_data_status(self, session: Session) -> LocalDataStatus:
        analytics = self._analytics_summary(session)
        return LocalDataStatus(
            database_url=self.db_url,
            database_path=_database_path_from_url(self.db_url),
            using_default_database=self.db_url == DEFAULT_DB_URL,
            source_count=self._count(session, CameraSourceModel),
            stream_count=self._count(session, StreamModel),
            zone_count=self._count(session, ZoneModel),
            event_count=analytics.event_count,
            visit_count=analytics.visit_count,
            media_asset_count=self._count(session, MediaAssetModel),
            detection_run_count=self._count(session, DetectionRunModel),
            detection_proposal_count=self._count(session, DetectionProposalModel),
            motion_evidence_count=self._count(session, MotionEvidenceModel),
            review_label_count=self._count(session, ReviewLabelModel),
            dataset_export_count=self._count(session, DatasetExportModel),
            needs_review_count=analytics.needs_review_count,
            database_ready=True,
            database_schema_version=self.schema_status.version,
            database_schema_current_version=self.schema_status.current_version,
            database_integrity_check=self.schema_status.integrity_check,
            seed_data_present=session.get(CameraSourceModel, demo_data.SOURCE_ID) is not None,
            local_first_note=(
                "MockingBird stores local product metadata, zones, corrections, "
                "review state, imported media references, analytics inputs, and "
                "dataset export manifests here. Imported media stays local and is "
                "not analyzed or transcoded in this phase."
            ),
        )

    def _count(self, session: Session, model: type) -> int:
        return session.scalar(select(func.count(model.id))) or 0

    def list_taxonomy_labels(self) -> list[TaxonomyLabel]:
        with self.session_factory() as session:
            labels = session.scalars(
                select(TaxonomyLabelModel).order_by(
                    TaxonomyLabelModel.sort_order,
                    TaxonomyLabelModel.id,
                )
            ).all()
            return [_taxonomy_label_from_model(label) for label in labels]

    def get_taxonomy_label(self, label: str) -> TaxonomyLabel | None:
        with self.session_factory() as session:
            model = self._taxonomy_label_model_for_input(session, label)
            return _taxonomy_label_from_model(model) if model else None

    def normalize_label(self, input_label: str) -> str:
        with self.session_factory() as session:
            return self._normalize_label_from_session(session, input_label)

    def label_suggestions(
        self,
        query: str | None = None,
        category: str | None = None,
    ) -> list[TaxonomyLabel]:
        with self.session_factory() as session:
            labels = session.scalars(
                select(TaxonomyLabelModel).order_by(
                    TaxonomyLabelModel.sort_order,
                    TaxonomyLabelModel.id,
                )
            ).all()
            query_key = _taxonomy_key(query or "")
            normalized_category = (category or "").strip().lower()
            suggestions: list[TaxonomyLabel] = []
            for label in labels:
                taxonomy_label = _taxonomy_label_from_model(label)
                if normalized_category:
                    if normalized_category == "species":
                        if not taxonomy_label.is_species:
                            continue
                    elif taxonomy_label.category.value != normalized_category:
                        continue

                if query_key:
                    search_values = [
                        taxonomy_label.id,
                        taxonomy_label.label,
                        taxonomy_label.display_name,
                        *taxonomy_label.aliases,
                    ]
                    if not any(query_key in _taxonomy_key(value) for value in search_values):
                        continue

                suggestions.append(taxonomy_label)
            return suggestions

    def list_sources(self) -> list[CameraSource]:
        with self.session_factory() as session:
            sources = session.scalars(select(CameraSourceModel).order_by(CameraSourceModel.id)).all()
            return [_source_from_model(source) for source in sources]

    def get_source(self, source_id: str) -> CameraSource | None:
        with self.session_factory() as session:
            source = session.get(CameraSourceModel, source_id)
            return _source_from_model(source) if source else None

    def create_camera_source(
        self,
        payload: CameraSourceCreate,
    ) -> CameraSourceCreateResponse:
        """Create durable Source/Stream context without connecting or creating evidence."""

        source_name = payload.name.strip()
        with self.session_factory() as session:
            with session.begin():
                existing_names = session.scalars(select(CameraSourceModel.name)).all()
                if any(name.strip().casefold() == source_name.casefold() for name in existing_names):
                    raise ValueError("source_name_exists")

                identifier = uuid.uuid4().hex[:12]
                source_model = CameraSourceModel(
                    id=f"source-{identifier}",
                    name=source_name,
                    kind=SourceKind.local_camera.value,
                    status=SourceStatus.needs_setup.value,
                    description="Outdoor camera ready to connect.",
                )
                stream_model = StreamModel(
                    id=f"stream-{identifier}",
                    source_id=source_model.id,
                    name=f"{source_name} stream",
                    description=f"Live outdoor stream for {source_name}.",
                    is_live=True,
                )
                policy_model, checkpoint_model = _new_stream_monitoring_records(
                    stream_model.id
                )
                session.add_all(
                    [source_model, stream_model, policy_model, checkpoint_model]
                )
                session.flush()
                return CameraSourceCreateResponse(
                    source=_source_from_model(source_model),
                    stream=_stream_from_model(stream_model),
                )

    def update_camera_source(
        self,
        source_id: str,
        payload: CameraSourceUpdate,
    ) -> CameraSourceMutationResult | None:
        """Rename or archive a camera while preserving its complete product graph."""

        with self.session_factory() as session:
            with session.begin():
                source = session.get(CameraSourceModel, source_id)
                if source is None:
                    return None
                if source.id == demo_data.SOURCE_ID or source.kind == SourceKind.demo.value:
                    raise ValueError("demo_source_immutable")

                streams = session.scalars(
                    select(StreamModel)
                    .where(StreamModel.source_id == source_id)
                    .order_by(StreamModel.id)
                ).all()
                if payload.name is not None:
                    source_name = payload.name.strip()
                    existing_names = session.scalars(
                        select(CameraSourceModel.name).where(CameraSourceModel.id != source_id)
                    ).all()
                    if any(
                        name.strip().casefold() == source_name.casefold()
                        for name in existing_names
                    ):
                        raise ValueError("source_name_exists")

                    previous_default_stream_name = f"{source.name} stream"
                    source.name = source_name
                    for stream in streams:
                        if stream.name == previous_default_stream_name:
                            stream.name = f"{source_name} stream"
                            stream.description = f"Live outdoor stream for {source_name}."

                if payload.archived is True:
                    source.status = SourceStatus.archived.value
                elif payload.archived is False and source.status == SourceStatus.archived.value:
                    source.status = SourceStatus.needs_setup.value

                session.flush()
                return CameraSourceMutationResult(
                    source=_source_from_model(source),
                    streams=[_stream_from_model(stream) for stream in streams],
                )

    def list_source_provider_definitions(self) -> list[SourceProviderDefinition]:
        return list(SOURCE_PROVIDER_DEFINITIONS)

    def camera_setup_options(self) -> CameraSetupOptionsResponse:
        """Expose only product-approved camera choices, never adapter class names."""

        options: list[CameraSetupOption] = []
        for definition in SOURCE_PROVIDER_DEFINITIONS:
            if definition.provider_key == "demo":
                continue
            available_now = definition.provider_key in {
                "external_url",
                "local_usb",
                "manual_media",
                "camera_node",
            }
            options.append(
                CameraSetupOption(
                    provider_key=definition.provider_key,
                    display_name=(
                        "IP / RTSP camera"
                        if definition.provider_key == "external_url"
                        else definition.display_name
                    ),
                    description=definition.description,
                    availability=(
                        "available_now"
                        if available_now
                        else "requires_future_adapter"
                    ),
                    supports_live_playback=definition.supports_live_playback,
                    fields=definition.fields,
                    message=(
                        (
                            "Pair a local Camera Node explicitly, then select one advertised camera. "
                            "Pairing is the only setup action that contacts a Node."
                            if definition.provider_key == "camera_node"
                            else "This computer supports configuring this provider; validation does not contact a camera."
                        )
                        if available_now
                        else "Local setup required before this provider can be configured here."
                    ),
                )
            )
        return CameraSetupOptionsResponse(
            options=options,
            message="Choose a provider MockingBird can configure locally on this computer.",
        )

    def validate_camera_setup(
        self,
        payload: CameraSetupValidationRequest,
    ) -> CameraSetupValidationResponse:
        """Validate bounded configuration/readiness without starting or monitoring a camera."""

        definition = _source_provider_definition(payload.provider_key)
        if definition is None or definition.provider_key == "demo":
            raise ValueError("camera_setup_provider_unsupported")
        allowed_fields = {field.key for field in definition.fields}
        unsupported = sorted(set(payload.config) - allowed_fields)
        if unsupported:
            raise ValueError("camera_setup_unsupported_fields")
        if definition.provider_key not in {"external_url", "local_usb", "manual_media", "camera_node"}:
            return CameraSetupValidationResponse(
                provider_key=definition.provider_key,
                status="unsupported_on_this_computer",
                message="Unsupported on this computer. This provider needs a future local adapter.",
                supports_live_playback=False,
                can_continue=False,
                preview_available=False,
            )

        sanitized = _sanitize_source_provider_config(definition, payload.config)
        _validate_camera_setup_urls(definition.provider_key, sanitized)
        draft_source = CameraSourceModel(
            id="camera-setup-draft",
            name="Camera setup draft",
            kind=_camera_setup_source_kind(definition.provider_key).value,
            status=SourceStatus.needs_setup.value,
            description="Temporary camera setup validation context.",
        )
        configuration = _source_provider_configuration_from_config(
            source_id=draft_source.id,
            definition=definition,
            config=sanitized,
            supports_zone_editing=True,
        )
        if configuration.missing_fields:
            status = "configuration_incomplete"
            message = configuration.message
            can_continue = False
        elif definition.provider_key == "local_usb" and not configuration.supports_live_playback:
            status = "local_setup_required"
            message = f"Local setup required. {configuration.message}"
            can_continue = True
        elif definition.provider_key == "external_url":
            status = "configuration_valid"
            message = "Configuration valid. Use Stream Detail later for any explicit preview."
            can_continue = True
        elif definition.provider_key == "camera_node":
            status = "configuration_valid"
            message = "Paired Camera Node configuration is valid. Snapshot preview and monitoring remain explicit."
            can_continue = True
        else:
            status = "configuration_valid"
            message = "Configuration valid. Complete setup to use the explicit local-media workflow."
            can_continue = True
        return CameraSetupValidationResponse(
            provider_key=definition.provider_key,
            status=status,
            message=message,
            safe_config_preview=configuration.safe_config_preview,
            supports_live_playback=configuration.supports_live_playback,
            can_continue=can_continue,
            preview_available=False,
        )

    def complete_camera_setup(
        self,
        payload: CameraSetupCompleteRequest,
    ) -> CameraSetupCompletionResponse:
        """Atomically create the product graph from a transient browser-local draft."""

        validation = self.validate_camera_setup(
            CameraSetupValidationRequest(
                provider_key=payload.provider_key,
                config=payload.config,
            )
        )
        if not validation.can_continue:
            raise ValueError("camera_setup_validation_required")
        definition = _source_provider_definition(payload.provider_key)
        assert definition is not None
        sanitized = _sanitize_source_provider_config(definition, payload.config)
        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                existing_operation = session.get(CameraSetupOperationModel, payload.idempotency_key)
                if existing_operation is not None:
                    source = session.get(CameraSourceModel, existing_operation.source_id)
                    stream = session.get(StreamModel, existing_operation.stream_id)
                    if source is None or stream is None:
                        raise ValueError("camera_setup_idempotency_conflict")
                    zones = self._zones_for_stream(session, stream.id)
                    policy = session.get(StreamMonitoringPolicyModel, stream.id)
                    assert policy is not None
                    return CameraSetupCompletionResponse(
                        source=_source_from_model(source),
                        stream=_stream_from_model(stream),
                        zones=zones,
                        monitoring_policy=_stream_monitoring_policy_from_model(stream, policy),
                        validation=validation,
                        idempotent=True,
                        message="Camera setup was already completed safely.",
                    )
                existing_names = session.scalars(select(CameraSourceModel.name)).all()
                if any(name.strip().casefold() == payload.camera_name.casefold() for name in existing_names):
                    raise ValueError("source_name_exists")
                identifier = uuid.uuid4().hex[:12]
                source = CameraSourceModel(
                    id=f"source-{identifier}",
                    name=payload.camera_name,
                    kind=_camera_setup_source_kind(definition.provider_key).value,
                    status=SourceStatus.connected.value,
                    description="Configured through guided Camera Setup.",
                )
                stream = StreamModel(
                    id=f"stream-{identifier}",
                    source_id=source.id,
                    name=payload.stream_name,
                    description=f"Camera view for {payload.camera_name}.",
                    is_live=definition.supports_live_playback,
                )
                policy, checkpoint = _new_stream_monitoring_records(stream.id, created_at=now)
                if payload.enable_monitoring:
                    policy.mode = StreamMonitoringMode.armed.value
                    policy.policy_revision = 2
                    policy.armed_at = now
                    policy.updated_at = now
                    checkpoint.observed_policy_revision = policy.policy_revision
                    checkpoint.last_stop_reason = None
                configuration = SourceProviderConfigurationModel(
                    source_id=source.id,
                    provider_key=definition.provider_key,
                    config_json=json.dumps(sanitized, sort_keys=True),
                    updated_at=now,
                )
                session.add_all((source, stream, policy, checkpoint, configuration))
                created_zones: list[Zone] = []
                for zone_draft in payload.zones:
                    zone = ZoneModel(
                        id=self._next_id(session, ZoneModel, "zone"),
                        stream_id=stream.id,
                        name=zone_draft.name,
                        zone_type=zone_draft.zone_type.value,
                        polygon_json=_points_to_json(zone_draft.polygon),
                        is_active=zone_draft.is_active,
                        monitoring_policy_json=(
                            json.dumps(
                                zone_draft.monitoring_policy.model_dump(
                                    exclude_none=True,
                                    mode="json",
                                ),
                                sort_keys=True,
                            )
                            if zone_draft.monitoring_policy is not None
                            and zone_draft.zone_type not in {ZoneType.privacy, ZoneType.ignore}
                            else None
                        ),
                    )
                    session.add(zone)
                    created_zones.append(_zone_from_model(zone))
                session.add(
                    CameraSetupOperationModel(
                        idempotency_key=payload.idempotency_key,
                        source_id=source.id,
                        stream_id=stream.id,
                        created_at=now,
                    )
                )
                session.flush()
                return CameraSetupCompletionResponse(
                    source=_source_from_model(source),
                    stream=_stream_from_model(stream),
                    zones=created_zones,
                    monitoring_policy=_stream_monitoring_policy_from_model(stream, policy),
                    validation=validation,
                    message=(
                        "Camera setup is complete. Monitoring is enabled as saved intent."
                        if payload.enable_monitoring
                        else "Camera setup is complete. Monitoring remains off until you enable it."
                    ),
                )

    def get_source_provider_configuration(
        self,
        source_id: str,
    ) -> SourceProviderConfiguration | None:
        with self.session_factory() as session:
            source = session.get(CameraSourceModel, source_id)
            if source is None:
                return None
            model = session.get(SourceProviderConfigurationModel, source_id)
            stream_ids = self._stream_ids_for_source(session, source_id)
            return _source_provider_configuration_from_model(source, model, stream_ids)

    def update_source_provider_configuration(
        self,
        source_id: str,
        payload: SourceProviderConfigurationUpdate,
    ) -> SourceProviderConfiguration | None:
        definition = _source_provider_definition(payload.provider_key)
        if definition is None:
            raise ValueError("unknown_provider_key")

        with self.session_factory() as session:
            with session.begin():
                source = session.get(CameraSourceModel, source_id)
                if source is None:
                    return None
                model = session.get(SourceProviderConfigurationModel, source_id)
                existing_config = json.loads(model.config_json) if model is not None else {}
                sanitized_config = _sanitize_source_provider_config(
                    definition,
                    payload.config,
                    existing_config,
                )
                if model is None:
                    model = SourceProviderConfigurationModel(
                        source_id=source_id,
                        provider_key=payload.provider_key,
                        config_json=json.dumps(sanitized_config, sort_keys=True),
                        updated_at=datetime.now(UTC),
                    )
                    session.add(model)
                else:
                    model.provider_key = payload.provider_key
                    model.config_json = json.dumps(sanitized_config, sort_keys=True)
                    model.updated_at = datetime.now(UTC)
                session.flush()
                stream_ids = self._stream_ids_for_source(session, source_id)
                return _source_provider_configuration_from_model(source, model, stream_ids)

    def get_camera_configuration_edit(
        self,
        stream_id: str,
    ) -> CameraConfigurationEditResponse | None:
        """Read one existing Stream's editable setup without returning saved settings."""

        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None
            source = session.get(CameraSourceModel, stream.source_id)
            if source is None:
                return None
            model = session.get(SourceProviderConfigurationModel, source.id)
            provider_key = model.provider_key if model is not None else _default_source_provider_key(source)
            definition = _source_provider_definition(provider_key)
            if definition is None:
                raise ValueError("camera_configuration_provider_unsupported")
            config = (
                json.loads(model.config_json)
                if model is not None
                else _default_source_provider_config(provider_key)
            )
            policy = session.get(StreamMonitoringPolicyModel, stream.id)
            checkpoint = session.get(StreamRuntimeCheckpointModel, stream.id)
            state_token = _camera_configuration_state_token(
                source=source,
                stream=stream,
                provider_key=provider_key,
                config=config,
                policy=policy,
                checkpoint=checkpoint,
            )
            summary = _source_provider_configuration_from_config(
                source_id=source.id,
                definition=definition,
                config=config,
                supports_zone_editing=definition.supports_zone_editing,
            )
            editable = _camera_configuration_is_editable(source, model, definition)
            editable_fields = [
                field.model_copy(update={"placeholder": None})
                for field in definition.fields
                if field.key in _camera_configuration_editable_field_keys(definition)
            ]
            field_states = {
                field.key: "configured"
                if (config.get(field.key) or "").strip()
                else "not_configured"
                for field in editable_fields
            }

        monitoring_policy = self.get_stream_monitoring_policy(stream_id)
        runtime = self.get_stream_runtime_status(stream_id)
        health = self.get_stream_camera_health(stream_id)
        if monitoring_policy is None or runtime is None or health is None:
            return None
        return CameraConfigurationEditResponse(
            stream_id=stream.id,
            source_id=source.id,
            source_name=source.name,
            stream_name=stream.name,
            provider_key=provider_key,
            provider_display_name=definition.display_name,
            editable=editable,
            editable_fields=editable_fields,
            configured_fields=[
                field.key for field in editable_fields if field_states[field.key] == "configured"
            ],
            missing_fields=[
                field_key
                for field_key in summary.missing_fields
                if field_key in field_states
            ],
            field_states=field_states,
            state_token=state_token,
            monitoring_policy=monitoring_policy,
            runtime=runtime,
            health=health.health,
            message=(
                "Edit this camera in place. Saved provider values remain masked."
                if editable
                else "This camera's provider configuration is not editable in guided setup."
            ),
        )

    def preview_camera_configuration(
        self,
        stream_id: str,
        payload: CameraConfigurationImpactPreviewRequest,
    ) -> CameraConfigurationImpactPreview | None:
        """Validate a proposed in-place edit and describe impact without touching runtime."""

        with self.session_factory() as session:
            state = _camera_configuration_state_for_stream(session, stream_id)
            if state is None:
                return None
            source, stream, model, definition, config, policy, checkpoint = state
            _validate_camera_configuration_request(
                source=source,
                model=model,
                definition=definition,
                payload=payload,
            )
            state_token = _camera_configuration_state_token(
                source=source,
                stream=stream,
                provider_key=model.provider_key,
                config=config,
                policy=policy,
                checkpoint=checkpoint,
            )
            if payload.expected_state_token != state_token:
                raise CameraConfigurationConflictError("camera_configuration_state_changed")
            proposed_config = _camera_configuration_proposed_config(
                definition=definition,
                existing_config=config,
                payload=payload,
            )
            validation = _camera_configuration_validation_summary(
                source_id=source.id,
                definition=definition,
                config=proposed_config,
            )
            changed_fields, changed_config_keys = _camera_configuration_changed_fields(
                source=source,
                stream=stream,
                definition=definition,
                previous_config=config,
                proposed_config=proposed_config,
                source_name=payload.source_name,
                stream_name=payload.stream_name,
            )
            restart_required = any(
                key not in _CAMERA_CONFIGURATION_NON_RUNTIME_FIELDS
                for key in changed_config_keys
            )
            change_fingerprint = _camera_configuration_change_fingerprint(
                source=source,
                stream=stream,
                proposed_config=proposed_config,
                source_name=payload.source_name,
                stream_name=payload.stream_name,
            )

        runtime = self.get_stream_runtime_status(stream_id)
        health = self.get_stream_camera_health(stream_id)
        if runtime is None or health is None:
            return None
        preview_token = _camera_configuration_preview_token(
            state_token=state_token,
            change_fingerprint=change_fingerprint,
        )
        return CameraConfigurationImpactPreview(
            stream_id=stream_id,
            source_id=source.id,
            provider_key=model.provider_key,
            state_token=state_token,
            preview_token=preview_token,
            changed_fields=changed_fields,
            restart_required=restart_required,
            requires_explicit_restart_choice=(
                restart_required and runtime.desired_mode == StreamMonitoringMode.armed
            ),
            monitoring_desired=runtime.desired_mode,
            monitoring_actual=runtime.actual_state,
            open_activity_session_count=health.health.open_activity_session_count,
            preview_may_be_briefly_unavailable=restart_required,
            preservation_summary=_camera_configuration_preservation_summary(),
            validation=validation,
            message=(
                "No saved settings would change."
                if not changed_fields
                else "This is a local configuration/readiness preview only; MockingBird does not contact the camera."
            ),
        )

    def camera_configuration_idempotent_revision(
        self,
        stream_id: str,
        payload: CameraConfigurationApplyRequest,
    ) -> CameraConfigurationRevision | None:
        """Return a matching completed apply once, without inspecting provider settings."""

        request_fingerprint = _camera_configuration_request_fingerprint(payload)
        with self.session_factory() as session:
            revision = session.scalar(
                select(CameraConfigurationRevisionModel).where(
                    CameraConfigurationRevisionModel.stream_id == stream_id,
                    CameraConfigurationRevisionModel.idempotency_key == payload.idempotency_key,
                )
            )
            if revision is None:
                return None
            if revision.request_fingerprint != request_fingerprint:
                raise CameraConfigurationConflictError("camera_configuration_idempotency_conflict")
            return _camera_configuration_revision_from_model(revision)

    def camera_configuration_preview_from_revision(
        self,
        stream_id: str,
        revision: CameraConfigurationRevision,
    ) -> CameraConfigurationImpactPreview | None:
        """Render an idempotent response from redacted local history only."""

        configuration = self.get_camera_configuration_edit(stream_id)
        if configuration is None:
            return None
        return CameraConfigurationImpactPreview(
            stream_id=stream_id,
            source_id=configuration.source_id,
            provider_key=revision.provider_key,
            state_token=configuration.state_token,
            preview_token=_camera_configuration_replay_preview_token(revision),
            changed_fields=revision.changed_fields,
            restart_required=revision.restart_required,
            requires_explicit_restart_choice=False,
            monitoring_desired=configuration.monitoring_policy.mode,
            monitoring_actual=configuration.runtime.actual_state,
            open_activity_session_count=configuration.health.open_activity_session_count,
            preview_may_be_briefly_unavailable=revision.restart_required,
            preservation_summary=_camera_configuration_preservation_summary(),
            validation=CameraConfigurationValidationSummary(
                status="already_applied",
                message="This configuration change was already applied safely.",
                missing_fields=configuration.missing_fields,
                can_apply=True,
            ),
            message="This configuration change was already applied safely.",
        )

    def apply_camera_configuration(
        self,
        stream_id: str,
        payload: CameraConfigurationApplyRequest,
    ) -> CameraConfigurationApplyResult | None:
        """Persist a previewed in-place edit atomically; callers own the runtime stop/wake."""

        existing = self.camera_configuration_idempotent_revision(stream_id, payload)
        if existing is not None:
            preview = self.camera_configuration_preview_from_revision(stream_id, existing)
            if preview is None:
                return None
            return CameraConfigurationApplyResult(
                revision=existing,
                preview=preview,
                idempotent=True,
            )

        preview = self.preview_camera_configuration(stream_id, payload)
        if preview is None:
            return None
        if preview.preview_token != payload.preview_token:
            raise CameraConfigurationConflictError("camera_configuration_preview_expired")
        if not preview.validation.can_apply:
            raise ValueError("camera_configuration_validation_required")
        if not preview.changed_fields:
            raise ValueError("camera_configuration_no_changes")

        request_fingerprint = _camera_configuration_request_fingerprint(payload)
        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                existing_model = session.scalar(
                    select(CameraConfigurationRevisionModel).where(
                        CameraConfigurationRevisionModel.stream_id == stream_id,
                        CameraConfigurationRevisionModel.idempotency_key == payload.idempotency_key,
                    )
                )
                if existing_model is not None:
                    if existing_model.request_fingerprint != request_fingerprint:
                        raise CameraConfigurationConflictError(
                            "camera_configuration_idempotency_conflict"
                        )
                    return CameraConfigurationApplyResult(
                        revision=_camera_configuration_revision_from_model(existing_model),
                        preview=self.camera_configuration_preview_from_revision(
                            stream_id,
                            _camera_configuration_revision_from_model(existing_model),
                        ) or preview,
                        idempotent=True,
                    )

                state = _camera_configuration_state_for_stream(session, stream_id)
                if state is None:
                    return None
                source, stream, model, definition, config, policy, checkpoint = state
                _validate_camera_configuration_request(
                    source=source,
                    model=model,
                    definition=definition,
                    payload=payload,
                )
                current_state_token = _camera_configuration_state_token(
                    source=source,
                    stream=stream,
                    provider_key=model.provider_key,
                    config=config,
                    policy=policy,
                    checkpoint=checkpoint,
                )
                if payload.expected_state_token != current_state_token:
                    raise CameraConfigurationConflictError("camera_configuration_state_changed")
                proposed_config = _camera_configuration_proposed_config(
                    definition=definition,
                    existing_config=config,
                    payload=payload,
                )
                validation = _camera_configuration_validation_summary(
                    source_id=source.id,
                    definition=definition,
                    config=proposed_config,
                )
                if not validation.can_apply:
                    raise ValueError("camera_configuration_validation_required")
                changed_fields, changed_config_keys = _camera_configuration_changed_fields(
                    source=source,
                    stream=stream,
                    definition=definition,
                    previous_config=config,
                    proposed_config=proposed_config,
                    source_name=payload.source_name,
                    stream_name=payload.stream_name,
                )
                if not changed_fields:
                    raise ValueError("camera_configuration_no_changes")
                restart_required = any(
                    key not in _CAMERA_CONFIGURATION_NON_RUNTIME_FIELDS
                    for key in changed_config_keys
                )
                change_fingerprint = _camera_configuration_change_fingerprint(
                    source=source,
                    stream=stream,
                    proposed_config=proposed_config,
                    source_name=payload.source_name,
                    stream_name=payload.stream_name,
                )
                if _camera_configuration_preview_token(
                    state_token=current_state_token,
                    change_fingerprint=change_fingerprint,
                ) != payload.preview_token:
                    raise CameraConfigurationConflictError("camera_configuration_preview_expired")

                if payload.source_name is not None and payload.source_name != source.name:
                    existing_names = session.scalars(
                        select(CameraSourceModel.name).where(CameraSourceModel.id != source.id)
                    ).all()
                    if any(
                        name.strip().casefold() == payload.source_name.casefold()
                        for name in existing_names
                    ):
                        raise ValueError("source_name_exists")
                    source.name = payload.source_name
                if payload.stream_name is not None:
                    stream.name = payload.stream_name
                model.config_json = json.dumps(proposed_config, sort_keys=True)
                model.updated_at = now

                actual_before = _stream_runtime_state_from_checkpoint(checkpoint)
                restart_requested = bool(
                    restart_required
                    and policy.mode == StreamMonitoringMode.armed.value
                    and payload.restart_monitoring
                )
                actual_after = actual_before
                if restart_required:
                    checkpoint.actual_state = StreamRuntimeState.stopped.value
                    checkpoint.observed_policy_revision = policy.policy_revision
                    checkpoint.app_instance_id = None
                    checkpoint.runtime_generation_id = None
                    checkpoint.next_retry_at = None
                    checkpoint.failure_code = None
                    checkpoint.consecutive_failure_count = 0
                    checkpoint.safety_hold_active = (
                        policy.mode == StreamMonitoringMode.armed.value and not restart_requested
                    )
                    checkpoint.last_clean_stop_at = now
                    checkpoint.last_stop_reason = (
                        "configuration_restart_requested"
                        if restart_requested
                        else "configuration_restart_deferred"
                    )
                    checkpoint.updated_at = now
                    actual_after = StreamRuntimeState.stopped

                revision_model = CameraConfigurationRevisionModel(
                    id=f"camera-config-{uuid.uuid4().hex[:16]}",
                    stream_id=stream.id,
                    source_id=source.id,
                    provider_key=model.provider_key,
                    changed_fields_json=json.dumps(changed_fields),
                    change_fingerprint=change_fingerprint,
                    request_fingerprint=request_fingerprint,
                    preview_token=payload.preview_token,
                    restart_required=restart_required,
                    restart_requested=restart_requested,
                    desired_mode=policy.mode,
                    actual_state_before=actual_before.value,
                    actual_state_after=actual_after.value,
                    outcome="applied",
                    idempotency_key=payload.idempotency_key,
                    created_at=now,
                )
                session.add(revision_model)
                session.flush()
                historical = session.scalars(
                    select(CameraConfigurationRevisionModel)
                    .where(CameraConfigurationRevisionModel.stream_id == stream.id)
                    .order_by(
                        CameraConfigurationRevisionModel.created_at.desc(),
                        CameraConfigurationRevisionModel.id.desc(),
                    )
                    .offset(CAMERA_CONFIGURATION_HISTORY_LIMIT)
                ).all()
                for historical_revision in historical:
                    session.delete(historical_revision)
                revision = _camera_configuration_revision_from_model(revision_model)

        return CameraConfigurationApplyResult(
            revision=revision,
            preview=preview,
            idempotent=False,
        )

    def list_camera_configuration_history(
        self,
        stream_id: str,
        *,
        limit: int = CAMERA_CONFIGURATION_HISTORY_LIMIT,
    ) -> list[CameraConfigurationRevision] | None:
        """Return bounded redacted configuration history; no provider configuration is read out."""

        bounded_limit = max(1, min(limit, CAMERA_CONFIGURATION_HISTORY_LIMIT))
        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None
            revisions = session.scalars(
                select(CameraConfigurationRevisionModel)
                .where(CameraConfigurationRevisionModel.stream_id == stream_id)
                .order_by(
                    CameraConfigurationRevisionModel.created_at.desc(),
                    CameraConfigurationRevisionModel.id.desc(),
                )
                .limit(bounded_limit)
            ).all()
            return [_camera_configuration_revision_from_model(revision) for revision in revisions]

    def camera_node_pairing_secret(self, stream_id: str) -> tuple[str, str] | None:
        """Internal-only credential lookup for an explicit pairing revocation call."""

        with self.session_factory() as session:
            state = _camera_configuration_state_for_stream(session, stream_id)
            if state is None:
                return None
            _, _, model, _, config, _, _ = state
            if model.provider_key != "camera_node":
                raise ValueError("camera_node_provider_required")
            address = (config.get("node_base_address") or "").strip()
            credential = (config.get("node_credential") or "").strip()
            return (address, credential) if address and credential else None

    def revoke_camera_node_pairing(self, stream_id: str) -> bool | None:
        """Remove only pairing access; product history and Source/Stream identity remain."""

        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                state = _camera_configuration_state_for_stream(session, stream_id)
                if state is None:
                    return None
                _, stream, model, _, config, policy, checkpoint = state
                if model.provider_key != "camera_node":
                    raise ValueError("camera_node_provider_required")
                if not (config.get("node_credential") or "").strip():
                    return False
                config.pop("node_credential", None)
                config["node_pairing_state"] = "revoked"
                model.config_json = json.dumps(config, sort_keys=True)
                model.updated_at = now
                checkpoint.actual_state = StreamRuntimeState.stopped.value
                checkpoint.app_instance_id = None
                checkpoint.runtime_generation_id = None
                checkpoint.safety_hold_active = policy.mode == StreamMonitoringMode.armed.value
                checkpoint.last_clean_stop_at = now
                checkpoint.last_stop_reason = "camera_node_pairing_revoked"
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, stream.id, now)
                return True

    def preview_source_folder_import(
        self,
        source_id: str,
        payload: SourceFolderImportPreviewRequest,
    ) -> SourceFolderImportPreviewResponse | None:
        with self.session_factory() as session:
            source = session.get(CameraSourceModel, source_id)
            if source is None:
                return None

            stream_ids = self._stream_ids_for_source(session, source_id)
            model = session.get(SourceProviderConfigurationModel, source_id)
            configuration = _source_provider_configuration_from_model(source, model, stream_ids)
            if configuration.provider_key != "folder_import_future":
                raise ValueError("folder_provider_required")

            config = json.loads(model.config_json) if model is not None else {}
            folder_path = (config.get("folder_path") or "").strip()
            config_recursive = _source_provider_bool(config.get("recursive"))
            config_allowed = _source_provider_list(config.get("allowed_extensions"))

        recursive = payload.recursive if payload.recursive is not None else config_recursive
        allowed_extensions = (
            payload.allowed_extensions
            if payload.allowed_extensions is not None
            else config_allowed
        )

        if not folder_path or folder_path == "configured":
            normalized_allowed, warnings = folder_import_preview.normalize_allowed_extensions(
                allowed_extensions
            )
            return SourceFolderImportPreviewResponse(
                source_id=source_id,
                provider_key="folder_import_future",
                folder_configured=False,
                recursive=recursive,
                allowed_extensions=normalized_allowed,
                candidates=[],
                skipped=[],
                total_candidates=0,
                total_skipped=0,
                total_known_bytes=0,
                unknown_size_count=0,
                scanned_at=datetime.now(UTC),
                dry_run=True,
                creates_media_assets=False,
                creates_events=False,
                creates_visits=False,
                creates_truth=False,
                warnings=[
                    "Folder path metadata is not configured; no folder was scanned.",
                    *warnings,
                ],
            )

        preview = folder_import_preview.preview_folder_import(
            folder_path,
            recursive=recursive,
            allowed_extensions=allowed_extensions,
            max_files=payload.max_files,
            max_depth=payload.max_depth,
        )
        return _source_folder_import_preview_response(
            source_id=source_id,
            preview=preview,
        )

    def import_source_folder_media_assets(
        self,
        source_id: str,
        payload: SourceFolderImportRequest,
    ) -> SourceFolderImportResponse | None:
        if payload.copy_mode != "copy_to_media_root":
            raise ValueError("unsupported_copy_mode")

        with self.session_factory() as session:
            source = session.get(CameraSourceModel, source_id)
            if source is None:
                return None

            stream_ids = self._stream_ids_for_source(session, source_id)
            model = session.get(SourceProviderConfigurationModel, source_id)
            configuration = _source_provider_configuration_from_model(source, model, stream_ids)
            if configuration.provider_key != "folder_import_future":
                raise ValueError("folder_provider_required")

            config = json.loads(model.config_json) if model is not None else {}
            folder_path = (config.get("folder_path") or "").strip()
            if not folder_path or folder_path == "configured":
                raise ValueError("folder_required")
            config_recursive = _source_provider_bool(config.get("recursive"))
            config_allowed = _source_provider_list(config.get("allowed_extensions"))
            config_stream_id = _clean_optional_text(config.get("default_stream_id"))
            config_zone_id = _clean_optional_text(config.get("default_zone_id"))

        recursive = payload.recursive if payload.recursive is not None else config_recursive
        allowed_extensions = (
            payload.allowed_extensions
            if payload.allowed_extensions is not None
            else config_allowed
        )
        selected_paths = (
            [path for path in payload.relative_paths if path.strip()]
            if payload.relative_paths is not None
            else None
        )
        if selected_paths is not None:
            preview = folder_import_preview.preview_folder_import_relative_paths(
                folder_path,
                selected_paths,
                allowed_extensions=allowed_extensions,
            )
        else:
            preview = folder_import_preview.preview_folder_import(
                folder_path,
                recursive=recursive,
                allowed_extensions=allowed_extensions,
                max_files=payload.max_files,
                max_depth=payload.max_depth,
            )

        imported_at = datetime.now(UTC)
        imported: list[SourceFolderImportCreatedMediaAsset] = []
        skipped = [
            SourceFolderImportSkipped(
                relative_path=item.relative_path,
                file_name=item.file_name,
                reason=item.reason,
                message=item.message,
            )
            for item in preview.skipped
        ]
        warnings = list(preview.warnings)
        total_bytes_copied = 0
        requested_stream_id = _clean_optional_text(payload.default_stream_id) or config_stream_id
        requested_zone_id = _clean_optional_text(payload.default_zone_id) or config_zone_id
        note = _clean_optional_text(payload.note)

        with self.session_factory() as session:
            with session.begin():
                stream_model, stream_warning = self._resolve_source_import_stream(
                    session,
                    source_id=source_id,
                    stream_id=requested_stream_id,
                )
                if stream_warning is not None:
                    warnings.append(stream_warning)
                zone_model = self._resolve_source_import_zone(
                    session,
                    zone_id=requested_zone_id,
                    stream_id=stream_model.id,
                )

                for candidate in preview.candidates:
                    content_type, media_type = SUPPORTED_MEDIA_EXTENSIONS[candidate.extension]
                    if self._folder_import_duplicate_exists(
                        session,
                        source_id=source_id,
                        relative_source_path=candidate.relative_path,
                        size_bytes=candidate.size_bytes,
                        modified_at=candidate.modified_at,
                    ):
                        skipped.append(
                            SourceFolderImportSkipped(
                                relative_path=candidate.relative_path,
                                file_name=candidate.file_name,
                                reason="already_imported",
                                message="This source file was already imported.",
                            )
                        )
                        continue

                    media_id = self._next_id(session, MediaAssetModel, "media-asset")
                    destination_name = (
                        f"{media_id}-folder-import-{_safe_filename(candidate.file_name)}"
                    )
                    try:
                        filename, local_path = self._copy_media_file(
                            destination_name,
                            candidate.source_path,
                        )
                        copied_size = local_path.stat().st_size
                    except OSError:
                        skipped.append(
                            SourceFolderImportSkipped(
                                relative_path=candidate.relative_path,
                                file_name=candidate.file_name,
                                reason="copy_error",
                                message="File could not be copied into local media storage.",
                            )
                        )
                        continue

                    asset_model = MediaAssetModel(
                        id=media_id,
                        source_id=source_id,
                        stream_id=stream_model.id,
                        filename=filename,
                        content_type=content_type,
                        media_type=media_type,
                        local_path=str(local_path),
                        original_filename=candidate.file_name,
                        file_size_bytes=copied_size,
                        created_at=imported_at,
                        notes=_folder_import_media_notes(
                            source_id=source_id,
                            stream_id=stream_model.id,
                            zone_id=zone_model.id if zone_model else None,
                            relative_source_path=candidate.relative_path,
                            original_filename=candidate.file_name,
                            size_bytes=candidate.size_bytes,
                            modified_at=candidate.modified_at,
                            imported_at=imported_at,
                            copy_mode=payload.copy_mode,
                            note=note,
                        ),
                    )
                    session.add(asset_model)
                    session.flush()
                    imported.append(
                        SourceFolderImportCreatedMediaAsset(
                            media_asset_id=media_id,
                            relative_source_path=candidate.relative_path,
                            file_name=candidate.file_name,
                            content_type=content_type,
                            size_bytes=copied_size,
                            stream_id=stream_model.id,
                            zone_id=zone_model.id if zone_model else None,
                            warnings=list(candidate.warnings),
                        )
                    )
                    total_bytes_copied += copied_size

        return SourceFolderImportResponse(
            source_id=source_id,
            provider_key="folder_import_future",
            imported=imported,
            skipped=skipped,
            total_imported=len(imported),
            total_skipped=len(skipped),
            total_bytes_copied=total_bytes_copied,
            imported_at=imported_at,
            copy_mode=payload.copy_mode,
            creates_media_assets=bool(imported),
            creates_motion_evidence=False,
            creates_events=False,
            creates_visits=False,
            creates_truth=False,
            warnings=warnings,
        )

    def get_source_connection_status(self, source_id: str) -> SourceConnectionStatus | None:
        with self.session_factory() as session:
            source = session.get(CameraSourceModel, source_id)
            if source is None:
                return None

            stream_ids = self._stream_ids_for_source(session, source_id)
            supports_zone_editing = len(stream_ids) > 0
            model = session.get(SourceProviderConfigurationModel, source_id)
            configuration = _source_provider_configuration_from_model(source, model, stream_ids)
            definition = _source_provider_definition(configuration.provider_key)
            provider_kind = _source_provider_kind(configuration.provider_key)

            source_archived = source.status == SourceStatus.archived.value
            if source_archived:
                status = SourceConnectionStatusValue.offline
                message = "This camera is archived and will not connect or monitor."
                setup_hint = "Restore the camera when you want to use its Stream again."
            elif source.status == SourceStatus.disconnected.value:
                status = SourceConnectionStatusValue.offline
                message = "This source is offline, so streams can show only placeholders."
                setup_hint = "Save provider metadata now; playback still requires a future provider."
            elif configuration.provider_key == "demo":
                status = SourceConnectionStatusValue.demo
                message = (
                    "This source uses local demo metadata and demo stream panels; "
                    "no real playback provider is connected yet."
                )
                setup_hint = (
                    "Future source providers will feed this contract while streams "
                    "and zones stay product-level."
                )
            elif configuration.missing_fields:
                status = SourceConnectionStatusValue.not_configured
                if configuration.provider_key == "folder_import_future":
                    message = (
                        "This source needs folder path metadata before explicit folder "
                        "preview/import can run."
                    )
                    setup_hint = (
                        "Add folder path metadata; MockingBird will not scan or import folders "
                        "from status."
                    )
                elif configuration.provider_key == "webhook_future":
                    message = (
                        "This source needs shared secret metadata before future webhook "
                        "validation or ingest can be implemented."
                    )
                    setup_hint = (
                        "Add shared secret metadata; MockingBird does not accept webhook "
                        "payloads yet."
                    )
                elif configuration.provider_key == "local_usb":
                    live_type = _normalize_live_stream_type(
                        configuration.safe_config_preview.get("live_stream_type")
                        or local_camera_bridge.LOCAL_USB_STREAM_TYPE,
                        "",
                    )
                    if live_type == windows_camera_bridge.WINDOWS_DSHOW_STREAM_TYPE:
                        message = (
                            "This source needs a Windows DirectShow camera name before "
                            "Live view can use the Windows camera bridge."
                        )
                        setup_hint = (
                            "Use Detect cameras in Cameras/Streams, then choose the connected "
                            "Windows webcam."
                        )
                    else:
                        message = (
                            "This source needs a local camera device path before Live view "
                            "can use the local camera bridge."
                        )
                        setup_hint = "Choose a local camera device such as /dev/video0."
                else:
                    message = (
                        "This source still needs provider metadata before a future provider can run."
                    )
                    setup_hint = configuration.setup_hint
            elif configuration.provider_key == "folder_import_future":
                status = SourceConnectionStatusValue.configured
                message = (
                    "Folder/trail-cam metadata is configured for explicit preview/import. "
                    "Folder import creates MediaAssets only, and live playback is not "
                    "expected for this provider."
                )
                setup_hint = (
                    "Preview or import folder media explicitly; evidence/review handoff "
                    "requires future scope."
                )
            elif configuration.provider_key == "webhook_future":
                status = SourceConnectionStatusValue.configured
                message = (
                    "Webhook metadata is configured for explicit motion-evidence ingest. "
                    "General webhook media/event ingest remains future work."
                )
                setup_hint = (
                    "Confirmed motion metadata can create pending MotionEvidence only; "
                    "media upload/download and reviewed truth remain future work."
                )
            elif provider_kind == SourceProviderKind.local_camera:
                status = SourceConnectionStatusValue.configured
                if configuration.supports_live_playback:
                    message = (
                        "Local camera metadata is ready for Live view through the "
                        "optional local bridge."
                    )
                    setup_hint = (
                        "Open Live view for playback; monitoring and review remain "
                        "separate explicit workflows."
                    )
                else:
                    message = (
                        "Local camera metadata is saved, but Live view needs an available "
                        "Linux camera device and host ffmpeg."
                    )
                    setup_hint = configuration.setup_hint
            elif definition is not None and definition.status == SourceProviderDefinitionStatus.future_adapter:
                status = SourceConnectionStatusValue.configured
                message = (
                    "Provider configuration metadata is saved. MockingBird will not connect "
                    "to this Source yet."
                )
                setup_hint = "Live playback requires a future provider implementation."
            elif provider_kind == SourceProviderKind.manual_media:
                status = SourceConnectionStatusValue.configured
                message = (
                    "Manual media provider metadata is ready for explicit local imports; "
                    "live playback is not expected for this provider."
                )
                setup_hint = (
                    "Import media for a related Source/Stream, then review and correct "
                    "Events/Visits before export."
                )
            elif provider_kind == SourceProviderKind.external_url:
                status = SourceConnectionStatusValue.configured
                if configuration.supports_live_playback:
                    message = (
                        "External URL metadata is ready for browser-direct live view and "
                        "explicit still-image preview fetch."
                    )
                    setup_hint = (
                        "Open Live view for playback; Test snapshot and Capture snapshot "
                        "remain separate explicit actions."
                    )
                else:
                    message = (
                        "External URL metadata is ready for explicit still-image preview fetch; "
                        "Live view needs a browser-playable stream URL."
                    )
                    setup_hint = (
                        "Add a Live stream URL for playback, or continue with snapshot "
                        "capture and monitoring."
                    )
            else:
                status = SourceConnectionStatusValue.configured
                message = (
                    "Provider configuration metadata is saved. MockingBird will not connect "
                    "to this Source yet."
                )
                setup_hint = "Zone editing can continue while playback remains unavailable."

            return SourceConnectionStatus(
                source_id=source.id,
                status=status,
                provider_kind=provider_kind,
                display_title=source.name,
                message=message,
                setup_hint=setup_hint,
                supports_streams=len(stream_ids) > 0,
                supports_live_playback=(
                    configuration.supports_live_playback and not source_archived
                ),
                supports_zone_editing=supports_zone_editing and not source_archived,
                adapter_key=configuration.provider_key,
                configured_fields=configuration.configured_fields,
                missing_fields=configuration.missing_fields,
                stream_ids=stream_ids,
            )

    def get_source_setup_review(self, source_id: str) -> SourceSetupReviewResponse | None:
        source = self.get_source(source_id)
        if source is None:
            return None

        configuration = self.get_source_provider_configuration(source_id)
        connection = self.get_source_connection_status(source_id)
        if configuration is None or connection is None:
            return None

        definition = _source_provider_definition(configuration.provider_key)
        provider_display_name = (
            definition.display_name if definition is not None else configuration.provider_key
        )
        streams = [
            playback
            for stream in self.streams_for_source(source_id)
            if (playback := self.get_stream_playback_status(stream.id)) is not None
        ]
        return _source_setup_review_from_contracts(
            source=source,
            configuration=configuration,
            connection=connection,
            provider_display_name=provider_display_name,
            definition=definition,
            streams=streams,
        )

    def validate_webhook_payload(
        self,
        source_id: str,
        payload: WebhookPayloadValidationRequest,
    ) -> WebhookPayloadValidationResponse | None:
        source = self.get_source(source_id)
        if source is None:
            return None

        configuration = self.get_source_provider_configuration(source_id)
        if configuration is None:
            return None
        if configuration.provider_key != "webhook_future":
            raise ValueError("webhook_provider_required")

        warnings = [
            "Webhook authentication is not implemented; this validation is dry-run only."
        ]
        if payload.shared_secret_marker:
            warnings.append("shared_secret_marker was treated as a dry-run marker only.")

        if (
            "shared_secret_configured" in configuration.missing_fields
            or configuration.safe_config_preview.get("shared_secret_configured") != "configured"
        ):
            return _webhook_payload_validation_response(
                source_id=source_id,
                valid=False,
                candidate=None,
                skipped_reason="not_configured",
                warnings=warnings
                + [
                    "Configure shared_secret_configured metadata before webhook validation can run."
                ],
            )

        payload_data = dict(payload.payload)
        candidate_summary = classify_webhook_payload(payload_data)
        warnings.extend(candidate_summary.warnings)

        allowed_source_name = _webhook_config_value(configuration, "allowed_source_name")
        payload_source_name = _webhook_payload_string(payload_data.get("source_name"))
        if allowed_source_name:
            if payload_source_name and payload_source_name != allowed_source_name:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=None,
                    zone_id=None,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="source_name_not_allowed",
                    warnings=warnings
                    + ["Payload source_name does not match the configured allowlist."],
                )
            if payload_source_name is None:
                warnings.append(
                    "Payload source_name is missing; configured allowed_source_name was not checked."
                )

        stream_id = (
            _webhook_payload_string(payload_data.get("stream_id"))
            or payload.default_stream_id
            or _webhook_config_value(configuration, "default_stream_id")
        )
        selected_stream_id: str | None = None
        if stream_id:
            stream = self.get_stream(stream_id)
            if stream is None:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=stream_id,
                    zone_id=None,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="stream_not_found",
                    warnings=warnings + ["Webhook payload stream_id was not found."],
                )
            if stream.source_id != source_id:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=stream_id,
                    zone_id=None,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="stream_source_mismatch",
                    warnings=warnings + ["Webhook payload stream_id does not belong to this Source."],
                )
            selected_stream_id = stream.id

        zone_id = (
            _webhook_payload_string(payload_data.get("zone_id"))
            or payload.default_zone_id
            or _webhook_config_value(configuration, "default_zone_id")
        )
        selected_zone_id: str | None = None
        if zone_id:
            zone = self.get_zone(zone_id)
            if zone is None:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=selected_stream_id,
                    zone_id=zone_id,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="zone_not_found",
                    warnings=warnings + ["Webhook payload zone_id was not found."],
                )

            if selected_stream_id is None:
                zone_stream = self.get_stream(zone.stream_id)
                if zone_stream is None or zone_stream.source_id != source_id:
                    candidate = _webhook_candidate_from_summary(
                        source_id=source_id,
                        stream_id=zone.stream_id,
                        zone_id=zone.id,
                        summary=candidate_summary,
                    )
                    return _webhook_payload_validation_response(
                        source_id=source_id,
                        valid=False,
                        candidate=candidate,
                        skipped_reason="zone_source_mismatch",
                        warnings=warnings + ["Webhook payload zone_id does not belong to this Source."],
                    )
                selected_stream_id = zone_stream.id
            elif zone.stream_id != selected_stream_id:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=selected_stream_id,
                    zone_id=zone.id,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="zone_stream_mismatch",
                    warnings=warnings + ["Webhook payload zone_id does not belong to the selected Stream."],
                )

            selected_zone_id = zone.id
            if zone.zone_type == ZoneType.privacy:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=selected_stream_id,
                    zone_id=selected_zone_id,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="privacy_zone",
                    warnings=warnings + ["Webhook payload targets a privacy zone."],
                )
            if zone.zone_type == ZoneType.ignore:
                candidate = _webhook_candidate_from_summary(
                    source_id=source_id,
                    stream_id=selected_stream_id,
                    zone_id=selected_zone_id,
                    summary=candidate_summary,
                )
                return _webhook_payload_validation_response(
                    source_id=source_id,
                    valid=False,
                    candidate=candidate,
                    skipped_reason="ignore_zone",
                    warnings=warnings + ["Webhook payload targets an ignore zone."],
                )

        if selected_stream_id is None and candidate_summary.candidate_type != "heartbeat":
            warnings.append("No Stream context was supplied; candidate remains unanchored.")

        candidate = _webhook_candidate_from_summary(
            source_id=source_id,
            stream_id=selected_stream_id,
            zone_id=selected_zone_id,
            summary=candidate_summary,
        )
        return _webhook_payload_validation_response(
            source_id=source_id,
            valid=candidate_summary.valid,
            candidate=candidate,
            skipped_reason=candidate_summary.skipped_reason,
            warnings=warnings,
        )

    def create_webhook_motion_evidence(
        self,
        source_id: str,
        payload: WebhookMotionEvidenceRequest,
    ) -> WebhookMotionEvidenceResponse | None:
        if not payload.confirm:
            raise ValueError("webhook_motion_evidence_confirmation_required")
        duplicate_policy = _clean_optional_text(payload.duplicate_policy) or "skip_existing"
        if duplicate_policy not in {"skip_existing", "allow_duplicate"}:
            raise ValueError("unsupported_duplicate_policy")

        validation = self.validate_webhook_payload(
            source_id,
            WebhookPayloadValidationRequest(
                payload=payload.payload,
                shared_secret_marker=payload.shared_secret_marker,
                default_stream_id=payload.default_stream_id,
                default_zone_id=payload.default_zone_id,
            ),
        )
        if validation is None:
            return None

        candidate = validation.candidate
        warnings = list(validation.warnings)

        if not validation.valid or candidate is None:
            return _webhook_motion_evidence_response(
                source_id=source_id,
                status="rejected",
                candidate_type=candidate.candidate_type if candidate else None,
                stream_id=candidate.stream_id if candidate else None,
                zone_id=candidate.zone_id if candidate else None,
                external_event_id=candidate.external_event_id if candidate else None,
                message=validation.skipped_reason
                or "Webhook payload did not validate for MotionEvidence creation.",
                warnings=warnings,
            )

        if candidate.candidate_type != "motion_event":
            return _webhook_motion_evidence_response(
                source_id=source_id,
                status="rejected",
                candidate_type=candidate.candidate_type,
                stream_id=candidate.stream_id,
                zone_id=candidate.zone_id,
                external_event_id=candidate.external_event_id,
                message="Only motion webhook payloads can create MotionEvidence in this phase.",
                warnings=warnings,
            )

        if candidate.stream_id is None:
            return _webhook_motion_evidence_response(
                source_id=source_id,
                status="rejected",
                candidate_type=candidate.candidate_type,
                stream_id=None,
                zone_id=candidate.zone_id,
                external_event_id=candidate.external_event_id,
                message="missing_stream_context",
                warnings=warnings
                + ["Choose a Stream or configure default_stream_id before creating MotionEvidence."],
            )
        if candidate.zone_id is None:
            return _webhook_motion_evidence_response(
                source_id=source_id,
                status="rejected",
                candidate_type=candidate.candidate_type,
                stream_id=candidate.stream_id,
                zone_id=None,
                external_event_id=candidate.external_event_id,
                message="missing_zone_context",
                warnings=warnings
                + ["Choose a Zone or configure default_zone_id before creating MotionEvidence."],
            )

        payload_data = dict(payload.payload)
        external_event_id = candidate.external_event_id
        if external_event_id is None:
            warnings.append(
                "external_event_id is missing; duplicate detection is limited for this payload."
            )

        with self.session_factory() as session:
            with session.begin():
                stream_model = session.get(StreamModel, candidate.stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")
                if stream_model.source_id != source_id:
                    raise ValueError("stream_source_mismatch")

                zone_model = session.get(ZoneModel, candidate.zone_id)
                if zone_model is None:
                    raise ValueError("missing_zone")
                if zone_model.stream_id != stream_model.id:
                    raise ValueError("zone_stream_mismatch")
                if zone_model.zone_type in {
                    ZoneType.privacy.value,
                    ZoneType.ignore.value,
                }:
                    raise ValueError("motion_evidence_creation_zone_blocked")

                existing_evidence = (
                    _existing_webhook_motion_evidence(
                        session=session,
                        source_id=source_id,
                        external_event_id=external_event_id,
                    )
                    if external_event_id is not None
                    else None
                )
                if existing_evidence is not None and duplicate_policy == "skip_existing":
                    warnings.append(
                        "Existing webhook MotionEvidence already uses this external_event_id; "
                        "no duplicate pending evidence was created."
                    )
                    return _webhook_motion_evidence_response(
                        source_id=source_id,
                        status="skipped",
                        motion_evidence_id=existing_evidence.id,
                        candidate_type=candidate.candidate_type,
                        stream_id=stream_model.id,
                        zone_id=zone_model.id,
                        external_event_id=external_event_id,
                        duplicate_skipped=True,
                        existing_motion_evidence_id=existing_evidence.id,
                        message="Existing webhook MotionEvidence matched this external_event_id.",
                        warnings=warnings,
                    )
                if existing_evidence is not None:
                    warnings.append(
                        "Existing webhook MotionEvidence already uses this external_event_id; "
                        "duplicate creation was allowed by policy."
                    )

                scoring_config = _webhook_motion_evidence_scoring_config(
                    source_id=source_id,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id,
                    external_event_id=external_event_id,
                    external_label=candidate.external_label,
                    external_confidence=candidate.external_confidence,
                    timestamp=_webhook_payload_string(payload_data.get("timestamp")),
                )
                note_parts = _webhook_motion_evidence_notes(
                    external_event_id=external_event_id,
                    external_label=candidate.external_label,
                    external_confidence=candidate.external_confidence,
                    timestamp=_webhook_payload_string(payload_data.get("timestamp")),
                    note=_clean_optional_text(payload.note),
                    reason=_clean_optional_text(payload.reason),
                )
                evidence_model = MotionEvidenceModel(
                    id=self._next_id(session, MotionEvidenceModel, "motion-evidence"),
                    source_id=source_id,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id,
                    start_frame_index=None,
                    end_frame_index=None,
                    best_frame_index=None,
                    start_time=_webhook_payload_string(payload_data.get("timestamp")),
                    end_time=None,
                    best_frame_time=None,
                    peak_changed_ratio=0.0,
                    triggered_frame_count=1,
                    scoring_config_json=json.dumps(scoring_config, sort_keys=True),
                    snapshot_media_asset_id=None,
                    status=MotionEvidenceStatus.pending.value,
                    promoted_event_id=None,
                    promoted_visit_id=None,
                    created_at=datetime.now(UTC),
                    notes="\n".join(note_parts),
                )
                session.add(evidence_model)
                session.flush()

                return _webhook_motion_evidence_response(
                    source_id=source_id,
                    status="created",
                    motion_evidence_id=evidence_model.id,
                    candidate_type=candidate.candidate_type,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id,
                    external_event_id=external_event_id,
                    message="Created pending MotionEvidence from webhook metadata.",
                    warnings=warnings,
                    creates_motion_evidence=True,
                )

    def list_streams(self) -> list[Stream]:
        with self.session_factory() as session:
            streams = session.scalars(select(StreamModel).order_by(StreamModel.id)).all()
            return [_stream_from_model(stream) for stream in streams]

    def get_stream(self, stream_id: str) -> Stream | None:
        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            return _stream_from_model(stream) if stream else None

    @staticmethod
    def _camera_health_reason(code: str | None) -> str | None:
        """Translate runtime codes once so operational views never expose internals."""

        return {
            "camera_unavailable": "Camera is not currently providing usable frames.",
            "node_unavailable": "MockingBird cannot currently reach the paired Camera Node API.",
            "authentication_rejected": "The paired Camera Node no longer accepts its local credential. Pair it again or revoke access.",
            "node_camera_unavailable": "The selected camera is not currently available on its paired Camera Node.",
            "node_camera_warmup_timeout": "The paired Camera Node did not finish warming its camera within the bounded window.",
            "node_snapshot_invalid": "The paired Camera Node did not provide a usable bounded image.",
            "node_snapshot_timeout": "The paired Camera Node did not provide a frame within the bounded snapshot window.",
            "provider_reset_required": "The paired Camera Node needs to reset its local camera provider.",
            "provider_session_failed": "The paired Camera Node is reopening its selected camera session.",
            "provider_warming": "The paired Camera Node is still warming its selected camera session.",
            "waiting_for_capacity": "Monitoring is waiting for available local capacity.",
            "evidence_persistence_failed": "MockingBird could not safely persist required evidence.",
            "configuration_invalid": "Camera setup needs review before monitoring can start.",
            "previous_process_ended": "Monitoring will resume when the local supervisor is ready.",
        }.get(code)

    def _camera_health_summary_from_models(
        self,
        session: Session,
        stream: StreamModel,
        *,
        source: CameraSourceModel | None,
        playback: StreamPlaybackStatus | None,
        now: datetime,
        open_activity_session_count: int = 0,
        latest_visit_at: datetime | None = None,
    ) -> CameraHealthSummary:
        """Resolve one product health state from durable intent and bounded checkpoints."""

        policy = session.get(StreamMonitoringPolicyModel, stream.id)
        checkpoint = session.get(StreamRuntimeCheckpointModel, stream.id)
        desired_mode = (
            StreamMonitoringMode(policy.mode)
            if policy is not None and policy.mode in StreamMonitoringMode._value2member_map_
            else StreamMonitoringMode.off
        )
        actual_state = StreamRuntimeState.stopped
        if checkpoint is not None and checkpoint.actual_state in StreamRuntimeState._value2member_map_:
            actual_state = StreamRuntimeState(checkpoint.actual_state)
        readiness_status = (
            playback.status if playback is not None else StreamPlaybackStatusValue.unknown
        )
        frame_at = normalize_optional_utc(
            checkpoint.last_healthy_frame_at if checkpoint is not None else None
        )
        frame_age_seconds = (
            max(0, int((_as_utc(now) - _as_utc(frame_at)).total_seconds()))
            if frame_at is not None
            else None
        )
        failure_code = (
            checkpoint.evidence_failure_code
            if checkpoint is not None and checkpoint.evidence_failure_code
            else checkpoint.failure_code if checkpoint is not None else None
        )

        # Frames are operational health signals. Wildlife activity and Visits are
        # deliberately absent from this decision so a quiet feeder can be healthy.
        if desired_mode != StreamMonitoringMode.armed:
            state = CameraHealthState.stopped
            message = "Monitoring is stopped by its saved local policy."
        elif source is None or source.status == SourceStatus.needs_setup.value or readiness_status in {
            StreamPlaybackStatusValue.not_configured,
            StreamPlaybackStatusValue.needs_stream_url,
        }:
            state = CameraHealthState.setup_incomplete
            message = "Camera setup is incomplete; review the saved configuration before monitoring."
            failure_code = "configuration_invalid"
        elif checkpoint is not None and checkpoint.evidence_failure_code:
            state = CameraHealthState.evidence_storage_degraded
            message = "Frames may be available, but required evidence persistence needs attention."
        elif (
            actual_state == StreamRuntimeState.blocked
            and checkpoint is not None
            and checkpoint.failure_code == "waiting_for_capacity"
        ):
            state = CameraHealthState.waiting_for_capacity
            message = "Monitoring is enabled and waiting for available local capacity."
        elif actual_state == StreamRuntimeState.backoff:
            node_message = {
                "node_unavailable": "MockingBird cannot reach the paired Camera Node API; bounded local recovery is scheduled.",
                "authentication_rejected": "The paired Camera Node rejected its credential; pair the Node again to restore monitoring.",
                "node_camera_unavailable": "The selected camera is unavailable on its paired Camera Node; bounded local recovery is scheduled.",
                "node_camera_warmup_timeout": "The paired Camera Node camera did not finish warming up; bounded local recovery is scheduled.",
                "node_snapshot_invalid": "The paired Camera Node did not provide a usable image; bounded local recovery is scheduled.",
                "node_snapshot_timeout": "The paired Camera Node did not provide a frame within the bounded snapshot window; recovery is scheduled.",
                "provider_reset_required": "The paired Camera Node is resetting its local camera provider before bounded recovery.",
            }.get(failure_code)
            if checkpoint is not None and checkpoint.consecutive_failure_count >= 3:
                state = CameraHealthState.camera_unavailable
                message = node_message or "The camera is unavailable after bounded recovery attempts."
            else:
                state = CameraHealthState.recovering
                message = node_message or "Monitoring is recovering through its bounded local retry path."
        elif actual_state == StreamRuntimeState.starting and checkpoint is not None and checkpoint.failure_code:
            state = (
                CameraHealthState.camera_unavailable
                if checkpoint.consecutive_failure_count >= 3
                else CameraHealthState.recovering
            )
            message = "Monitoring is retrying after a bounded camera failure."
        elif actual_state == StreamRuntimeState.starting:
            startup_age = (
                _as_utc(now) - _as_utc(checkpoint.last_start_attempt_at)
                if checkpoint is not None and checkpoint.last_start_attempt_at is not None
                else timedelta(0)
            )
            if startup_age <= CAMERA_HEALTH_STARTUP_GRACE:
                state = CameraHealthState.starting
                message = "Monitoring is starting and waiting for its first usable frame."
            else:
                state = CameraHealthState.camera_unavailable
                message = "The camera did not provide a usable frame during the startup window."
        elif actual_state == StreamRuntimeState.running:
            if frame_at is None:
                startup_age = (
                    _as_utc(now) - _as_utc(checkpoint.last_start_attempt_at)
                    if checkpoint is not None and checkpoint.last_start_attempt_at is not None
                    else timedelta(0)
                )
                if startup_age <= CAMERA_HEALTH_STARTUP_GRACE:
                    state = CameraHealthState.starting
                    message = "Monitoring is running and waiting for its first usable frame."
                else:
                    state = CameraHealthState.no_recent_frame
                    message = "Monitoring is running, but no usable frame has arrived recently."
            elif frame_age_seconds is not None and frame_age_seconds <= int(CAMERA_HEALTH_RECENT_FRAME.total_seconds()):
                state = CameraHealthState.healthy
                message = "Monitoring is running and recently received a usable frame."
            else:
                state = CameraHealthState.no_recent_frame
                message = "Monitoring is running, but its last usable frame is no longer recent."
        elif actual_state == StreamRuntimeState.blocked:
            state = CameraHealthState.camera_unavailable
            message = {
                "node_unavailable": "MockingBird cannot reach the paired Camera Node API. Check the local Node and use retry when ready.",
                "authentication_rejected": "The paired Camera Node rejected its credential. Pair the Node again before retrying.",
                "node_camera_unavailable": "The selected camera is unavailable on its paired Camera Node. Check that camera before retrying.",
                "node_camera_warmup_timeout": "The paired Camera Node camera did not finish warming up. Try again shortly.",
                "node_snapshot_invalid": "The paired Camera Node did not provide a usable image. Check the Node before retrying.",
                "node_snapshot_timeout": "The paired Camera Node did not provide a frame within the bounded snapshot window. Try again shortly.",
                "provider_reset_required": "The paired Camera Node needs to reset its local camera provider before retrying.",
            }.get(failure_code, "Monitoring needs attention before the camera can restart.")
        elif checkpoint is not None and (
            checkpoint.next_retry_at is not None
            or checkpoint.last_stop_reason == "retry_requested"
        ):
            state = CameraHealthState.recovering
            message = "Monitoring is preparing a bounded local retry."
        elif checkpoint is not None and checkpoint.failure_code:
            state = CameraHealthState.camera_unavailable
            message = {
                "node_unavailable": "MockingBird cannot reach the paired Camera Node API.",
                "authentication_rejected": "The paired Camera Node rejected its credential. Pair the Node again before retrying.",
                "node_camera_unavailable": "The selected camera is unavailable on its paired Camera Node.",
                "node_camera_warmup_timeout": "The paired Camera Node camera did not finish warming up.",
                "node_snapshot_invalid": "The paired Camera Node did not provide a usable image.",
                "node_snapshot_timeout": "The paired Camera Node did not provide a frame within the bounded snapshot window.",
                "provider_reset_required": "The paired Camera Node needs to reset its local camera provider.",
            }.get(failure_code, "The camera is unavailable and needs attention before it can restart.")
        else:
            state = CameraHealthState.starting
            message = "Monitoring is enabled and awaiting local supervision."

        unread_alert = bool(
            session.scalar(
                select(ProductAlertModel.id)
                .where(
                    ProductAlertModel.stream_id == stream.id,
                    ProductAlertModel.category == AlertCategory.monitoring.value,
                    ProductAlertModel.read_at.is_(None),
                    ProductAlertModel.dismissed_at.is_(None),
                    ProductAlertModel.resolved_at.is_(None),
                )
                .limit(1)
            )
        )
        stale = bool(
            checkpoint is not None
            and desired_mode == StreamMonitoringMode.armed
            and _as_utc(checkpoint.updated_at) < _as_utc(now) - CAMERA_HEALTH_DEGRADED_FRAME
        )
        return CameraHealthSummary(
            stream_id=stream.id,
            stream_name=stream.name,
            source_id=stream.source_id,
            source_name=source.name if source is not None else "Unavailable Source",
            state=state,
            message=message,
            desired_mode=desired_mode,
            actual_state=actual_state,
            readiness_status=readiness_status,
            preview_available=readiness_status
            in {StreamPlaybackStatusValue.demo, StreamPlaybackStatusValue.live_ready},
            last_good_frame_at=frame_at,
            frame_age_seconds=frame_age_seconds,
            last_evidence_persisted_at=normalize_optional_utc(
                checkpoint.last_evidence_persisted_at if checkpoint is not None else None
            ),
            last_evidence_failure_at=normalize_optional_utc(
                checkpoint.last_evidence_failure_at if checkpoint is not None else None
            ),
            open_activity_session_count=open_activity_session_count,
            latest_visit_at=normalize_optional_utc(latest_visit_at),
            next_retry_at=normalize_optional_utc(
                checkpoint.next_retry_at if checkpoint is not None else None
            ),
            failure_reason=self._camera_health_reason(failure_code),
            unread_alert=unread_alert,
            stale=stale,
        )

    @staticmethod
    def _camera_health_incident_from_model(
        incident: CameraHealthIncidentModel,
    ) -> CameraHealthIncident:
        return CameraHealthIncident(
            id=incident.id,
            stream_id=incident.stream_id,
            category=CameraHealthIncidentCategory(incident.category),
            severity=AlertSeverity(incident.severity),
            started_at=normalize_utc(incident.started_at),
            updated_at=normalize_utc(incident.updated_at),
            resolved_at=normalize_optional_utc(incident.resolved_at),
            reason_code=incident.reason_code,
            condition_fingerprint=incident.condition_fingerprint,
            next_retry_at=normalize_optional_utc(incident.next_retry_at),
            occurrence_count=min(CAMERA_HEALTH_MAX_OCCURRENCES, incident.occurrence_count),
            alert_id=incident.alert_id,
        )

    def _camera_health_incident_condition(
        self,
        health: CameraHealthSummary,
        checkpoint: StreamRuntimeCheckpointModel | None,
        *,
        now: datetime,
    ) -> tuple[CameraHealthIncidentCategory, AlertSeverity, str, str, str, str] | None:
        if health.state == CameraHealthState.setup_incomplete:
            return (
                CameraHealthIncidentCategory.configuration_invalid,
                AlertSeverity.warning,
                "configuration_invalid",
                "setup_incomplete",
                "Camera setup needs review",
                "This enabled camera needs a complete saved setup before monitoring can start.",
            )
        if health.state == CameraHealthState.evidence_storage_degraded:
            return (
                CameraHealthIncidentCategory.evidence_persistence_degraded,
                AlertSeverity.high,
                "evidence_persistence_failed",
                "evidence_persistence_degraded",
                "Evidence storage needs attention",
                "Frames may be available, but MockingBird could not safely persist required evidence.",
            )
        if health.state == CameraHealthState.waiting_for_capacity:
            if (
                checkpoint is None
                or _as_utc(checkpoint.updated_at) > _as_utc(now) - CAMERA_HEALTH_PROLONGED_CAPACITY_WAIT
            ):
                return None
            return (
                CameraHealthIncidentCategory.capacity_waiting,
                AlertSeverity.warning,
                "waiting_for_capacity",
                "capacity_waiting",
                "Monitoring is waiting for capacity",
                "This enabled camera has been waiting for available local monitoring capacity.",
            )
        if health.state == CameraHealthState.no_recent_frame:
            if health.frame_age_seconds is None or health.frame_age_seconds < int(CAMERA_HEALTH_DEGRADED_FRAME.total_seconds()):
                return None
            return (
                CameraHealthIncidentCategory.no_recent_frame,
                AlertSeverity.warning,
                "no_recent_frame",
                "no_recent_frame",
                "Camera frame is no longer recent",
                "Monitoring is running, but the camera has not provided a usable frame within the expected interval.",
            )
        if health.state == CameraHealthState.camera_unavailable:
            exhausted = bool(checkpoint and checkpoint.consecutive_failure_count >= 2)
            node_failure = (
                checkpoint.failure_code
                if checkpoint is not None
                and checkpoint.failure_code
                in CAMERA_NODE_RUNTIME_FAILURE_CODES
                else None
            )
            title, body = {
                "node_unavailable": (
                    "Camera Node is unreachable",
                    "MockingBird cannot reach this paired Camera Node API. Check its local network and power before retrying.",
                ),
                "authentication_rejected": (
                    "Camera Node pairing needs attention",
                    "This paired Camera Node rejected its credential. Re-pair the Node or revoke it before retrying.",
                ),
                "node_camera_unavailable": (
                    "Camera Node camera is unavailable",
                    "The selected camera is not currently available on its paired Camera Node. Check that local camera before retrying.",
                ),
                "node_camera_warmup_timeout": (
                    "Camera Node warm-up timed out",
                    "The paired Camera Node did not finish warming its camera within the bounded window. MockingBird will recover conservatively.",
                ),
                "node_snapshot_invalid": (
                    "Camera Node image needs attention",
                    "The paired Camera Node did not provide a usable image. Check its local camera setup before retrying.",
                ),
                "node_snapshot_timeout": (
                    "Camera Node snapshot timed out",
                    "The paired Camera Node did not provide a frame within the bounded snapshot window. MockingBird will recover conservatively.",
                ),
                "provider_reset_required": (
                    "Camera Node provider needs a reset",
                    "The paired Camera Node needs to reset its local camera provider before retrying.",
                ),
            }.get(
                node_failure,
                (
                    "Camera recovery needs attention" if exhausted else "Camera is unavailable",
                    "This enabled camera is unavailable after bounded local recovery attempts."
                    if exhausted
                    else "This enabled camera is not currently providing usable frames.",
                ),
            )
            return (
                CameraHealthIncidentCategory.recovery_exhausted
                if exhausted
                else CameraHealthIncidentCategory.camera_unavailable,
                AlertSeverity.high if exhausted else AlertSeverity.warning,
                node_failure or "camera_unavailable",
                (
                    f"{node_failure}_recovery"
                    if node_failure
                    else "recovery_exhausted"
                ),
                title,
                body,
            )
        if health.state == CameraHealthState.recovering and checkpoint is not None and checkpoint.consecutive_failure_count >= 2:
            node_failure = (
                checkpoint.failure_code
                if checkpoint.failure_code
                in CAMERA_NODE_RUNTIME_FAILURE_CODES
                else None
            )
            title, body = {
                "node_unavailable": (
                    "Camera Node recovery is in progress",
                    "MockingBird is using its bounded local retry path while the paired Camera Node remains unreachable.",
                ),
                "authentication_rejected": (
                    "Camera Node pairing needs attention",
                    "MockingBird is using its bounded retry path, but this paired Camera Node rejected its credential. Re-pair it to restore monitoring.",
                ),
                "node_camera_unavailable": (
                    "Camera Node camera recovery is in progress",
                    "MockingBird is using its bounded local retry path while the selected Camera Node camera is unavailable.",
                ),
                "node_camera_warmup_timeout": (
                    "Camera Node warm-up recovery is in progress",
                    "MockingBird is using its bounded local retry path while the paired Camera Node camera warms up.",
                ),
                "node_snapshot_invalid": (
                    "Camera Node image recovery is in progress",
                    "MockingBird is using its bounded local retry path after an unusable Camera Node image.",
                ),
                "node_snapshot_timeout": (
                    "Camera Node snapshot recovery is in progress",
                    "MockingBird is using its bounded local retry path after a bounded Camera Node snapshot timeout.",
                ),
                "provider_reset_required": (
                    "Camera Node provider recovery is in progress",
                    "MockingBird is using its bounded local retry path while the paired Camera Node resets its local camera provider.",
                ),
            }.get(
                node_failure,
                (
                    "Camera recovery is in progress",
                    "MockingBird is using its bounded local retry path for this enabled camera.",
                ),
            )
            return (
                CameraHealthIncidentCategory.recovery_exhausted,
                AlertSeverity.warning,
                node_failure or "camera_unavailable",
                "recovery_exhausted" if node_failure is None else f"{node_failure}_recovery",
                title,
                body,
            )
        return None

    def _resolve_camera_health_state(
        self,
        session: Session,
        stream_id: str,
        now: datetime,
    ) -> None:
        prefix = f"monitoring:{stream_id}:"
        for incident in session.scalars(
            select(CameraHealthIncidentModel).where(
                CameraHealthIncidentModel.stream_id == stream_id,
                CameraHealthIncidentModel.resolved_at.is_(None),
            )
        ).all():
            incident.resolved_at = now
            incident.updated_at = now
        for alert in session.scalars(
            select(ProductAlertModel).where(
                ProductAlertModel.deduplication_key.like(f"{prefix}%"),
                ProductAlertModel.resolved_at.is_(None),
            )
        ).all():
            alert.resolved_at = now
            alert.updated_at = now
        history = session.scalars(
            select(CameraHealthIncidentModel)
            .where(
                CameraHealthIncidentModel.stream_id == stream_id,
            )
            .order_by(
                CameraHealthIncidentModel.updated_at.desc(),
                CameraHealthIncidentModel.id.desc(),
            )
        ).all()
        for historical in history[CAMERA_HEALTH_HISTORY_LIMIT:]:
            if historical.resolved_at is not None:
                session.delete(historical)

    def _sync_camera_health_incident(
        self,
        session: Session,
        stream_id: str,
        now: datetime,
    ) -> None:
        stream = session.get(StreamModel, stream_id)
        policy = session.get(StreamMonitoringPolicyModel, stream_id)
        checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
        if (
            stream is None
            or policy is None
            or policy.mode != StreamMonitoringMode.armed.value
        ):
            self._resolve_camera_health_state(session, stream_id, now)
            return
        try:
            playback = self.get_stream_playback_status(stream_id)
        except Exception:
            playback = None
        source = session.get(CameraSourceModel, stream.source_id)
        health = self._camera_health_summary_from_models(
            session,
            stream,
            source=source,
            playback=playback,
            now=now,
        )
        condition = self._camera_health_incident_condition(
            health,
            checkpoint,
            now=now,
        )
        if condition is None:
            self._resolve_camera_health_state(session, stream_id, now)
            return
        category, severity, reason_code, fingerprint, title, message = condition
        prefix = f"monitoring:{stream_id}:"
        for incident in session.scalars(
            select(CameraHealthIncidentModel).where(
                CameraHealthIncidentModel.stream_id == stream_id,
                CameraHealthIncidentModel.resolved_at.is_(None),
                CameraHealthIncidentModel.condition_fingerprint != fingerprint,
            )
        ).all():
            incident.resolved_at = now
            incident.updated_at = now
        for alert in session.scalars(
            select(ProductAlertModel).where(
                ProductAlertModel.deduplication_key.like(f"{prefix}%"),
                ProductAlertModel.resolved_at.is_(None),
                ProductAlertModel.condition_fingerprint != fingerprint,
            )
        ).all():
            alert.resolved_at = now
            alert.updated_at = now
        incident = session.scalar(
            select(CameraHealthIncidentModel)
            .where(
                CameraHealthIncidentModel.stream_id == stream_id,
                CameraHealthIncidentModel.condition_fingerprint == fingerprint,
                CameraHealthIncidentModel.resolved_at.is_(None),
            )
            .order_by(CameraHealthIncidentModel.updated_at.desc())
        )
        if incident is None:
            incident = CameraHealthIncidentModel(
                id=uuid.uuid4().hex,
                stream_id=stream_id,
                category=category.value,
                severity=severity.value,
                started_at=now,
                updated_at=now,
                resolved_at=None,
                reason_code=reason_code,
                condition_fingerprint=fingerprint,
                next_retry_at=health.next_retry_at,
                occurrence_count=1,
                alert_id=None,
            )
            session.add(incident)
        else:
            incident.updated_at = now
            incident.severity = severity.value
            incident.reason_code = reason_code
            incident.next_retry_at = health.next_retry_at
            if checkpoint is not None:
                incident.occurrence_count = min(
                    CAMERA_HEALTH_MAX_OCCURRENCES,
                    max(incident.occurrence_count, checkpoint.failure_count),
                )
        alert = self._refresh_product_alert(
            session,
            category=AlertCategory.monitoring,
            severity=severity,
            title=title,
            message=message,
            deduplication_key=f"{prefix}{fingerprint}",
            condition_fingerprint=fingerprint,
            action_type=AlertActionType.open_stream,
            action_parameters={},
            now=now,
            stream_id=stream.id,
            source_id=stream.source_id,
        )
        incident.alert_id = alert.id
        history = session.scalars(
            select(CameraHealthIncidentModel)
            .where(
                CameraHealthIncidentModel.stream_id == stream_id,
            )
            .order_by(
                CameraHealthIncidentModel.updated_at.desc(),
                CameraHealthIncidentModel.id.desc(),
            )
        ).all()
        for historical in history[CAMERA_HEALTH_HISTORY_LIMIT:]:
            if historical.resolved_at is not None:
                session.delete(historical)

    def get_stream_camera_health(
        self,
        stream_id: str,
        *,
        incident_limit: int = CAMERA_HEALTH_HISTORY_LIMIT,
    ) -> CameraHealthDetailResponse | None:
        """Read bounded health only; it never reconciles, probes, or starts a camera."""

        bounded_limit = max(1, min(incident_limit, CAMERA_HEALTH_HISTORY_LIMIT))
        try:
            playback = self.get_stream_playback_status(stream_id)
        except Exception:
            playback = None
        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None
            source = session.get(CameraSourceModel, stream.source_id)
            latest_visit_at = session.scalar(
                select(EventModel.started_at)
                .where(EventModel.stream_id == stream_id)
                .order_by(EventModel.started_at.desc(), EventModel.id.desc())
                .limit(1)
            )
            open_sessions = session.scalar(
                select(func.count(EventModel.id)).where(
                    EventModel.stream_id == stream_id,
                    EventModel.ended_at.is_(None),
                )
            ) or 0
            health = self._camera_health_summary_from_models(
                session,
                stream,
                source=source,
                playback=playback,
                now=datetime.now(UTC),
                open_activity_session_count=open_sessions,
                latest_visit_at=latest_visit_at,
            )
            incidents = [
                self._camera_health_incident_from_model(incident)
                for incident in session.scalars(
                    select(CameraHealthIncidentModel)
                    .where(CameraHealthIncidentModel.stream_id == stream_id)
                    .order_by(
                        CameraHealthIncidentModel.updated_at.desc(),
                        CameraHealthIncidentModel.id.desc(),
                    )
                    .limit(bounded_limit)
                ).all()
            ]
            return CameraHealthDetailResponse(
                health=health,
                incidents=incidents,
                message="Showing saved camera health and bounded recent operational history.",
            )

    def list_stream_camera_health(
        self,
        *,
        limit: int = 50,
    ) -> list[CameraHealthSummary]:
        """Return a bounded all-Stream health summary without altering monitoring intent."""

        return [
            detail.health
            for stream in self.list_streams()[: max(1, min(limit, 50))]
            if (detail := self.get_stream_camera_health(stream.id, incident_limit=1)) is not None
        ]

    def get_stream_monitoring_policy(
        self,
        stream_id: str,
    ) -> StreamMonitoringPolicyResponse | None:
        """Read durable intent without reconciling or starting runtime activity."""

        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None
            model = session.get(StreamMonitoringPolicyModel, stream_id)
            if model is None:
                return StreamMonitoringPolicyResponse(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    mode=StreamMonitoringMode.off,
                    auto_create_review_candidates=False,
                    evaluation_interval_seconds=(
                        DEFAULT_STREAM_MONITORING_INTERVAL_SECONDS
                    ),
                    quiet_period_seconds=DEFAULT_STREAM_MONITORING_QUIET_SECONDS,
                    minimum_detection_count=(
                        DEFAULT_STREAM_MONITORING_MINIMUM_DETECTIONS
                    ),
                    policy_revision=1,
                    persisted=False,
                    message=(
                        "Monitoring is disabled. The missing saved record is shown as "
                        "the safe default."
                    ),
                    warnings=[
                        "The persisted policy record is missing; the safe off default is shown."
                    ],
                )
            return StreamMonitoringPolicyResponse(
                stream_id=stream.id,
                source_id=stream.source_id,
                mode=StreamMonitoringMode(model.mode),
                auto_create_review_candidates=model.auto_create_review_candidates,
                evaluation_interval_seconds=model.evaluation_interval_seconds,
                quiet_period_seconds=model.quiet_period_seconds,
                minimum_detection_count=model.minimum_detection_count,
                policy_revision=model.policy_revision,
                armed_at=model.armed_at,
                paused_at=model.paused_at,
                updated_at=model.updated_at,
                pause_reason=model.pause_reason,
                persisted=True,
                message=(
                    "Monitoring is disabled. Enable it explicitly from Stream Detail "
                    "when this camera is ready."
                    if model.mode == StreamMonitoringMode.off.value
                    else "Monitoring is enabled and will be restored by the local supervisor."
                    if model.mode == StreamMonitoringMode.armed.value
                    else "Monitoring is paused and will not start until it is enabled again."
                ),
            )

    def get_stream_runtime_status(
        self,
        stream_id: str,
    ) -> StreamRuntimeStatusResponse | None:
        """Read last-known continuity metadata without touching any runtime manager."""

        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None
            policy = session.get(StreamMonitoringPolicyModel, stream_id)
            checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
            desired_mode = (
                StreamMonitoringMode(policy.mode)
                if policy is not None
                else StreamMonitoringMode.off
            )
            warnings: list[str] = []
            if policy is None:
                warnings.append(
                    "The persisted policy record is missing; the safe off default is shown."
                )

            actual_state = StreamRuntimeState.stopped
            if checkpoint is not None:
                try:
                    actual_state = StreamRuntimeState(checkpoint.actual_state)
                except ValueError:
                    checkpoint_state = StreamRuntimeState.interrupted
                    warnings.append("The last runtime checkpoint has an unknown state.")
                    actual_state = checkpoint_state

            if desired_mode == StreamMonitoringMode.off:
                message = "Monitoring is disabled; no camera or monitor start is requested."
            elif desired_mode == StreamMonitoringMode.paused:
                message = "Monitoring is paused; no camera or monitor start is requested."
            elif actual_state == StreamRuntimeState.running:
                message = "Monitoring is running."
            elif actual_state == StreamRuntimeState.starting:
                message = "Monitoring is starting and waiting for a healthy live frame."
            elif (
                actual_state == StreamRuntimeState.blocked
                and checkpoint is not None
                and checkpoint.failure_code == "waiting_for_capacity"
            ):
                message = "Monitoring is enabled and waiting for available local capacity."
            elif actual_state == StreamRuntimeState.backoff:
                message = "Monitoring is enabled and will retry after a bounded backoff."
            elif actual_state == StreamRuntimeState.blocked:
                message = "Monitoring needs attention before it can restart."
            else:
                message = "Monitoring is enabled and awaiting local supervision."

            return StreamRuntimeStatusResponse(
                stream_id=stream.id,
                source_id=stream.source_id,
                desired_mode=desired_mode,
                actual_state=actual_state,
                observed_policy_revision=(
                    checkpoint.observed_policy_revision
                    if checkpoint is not None
                    else policy.policy_revision
                    if policy is not None
                    else 1
                ),
                checkpoint_present=checkpoint is not None,
                active_session_count=(
                    1
                    if desired_mode == StreamMonitoringMode.armed
                    and actual_state
                    in {StreamRuntimeState.starting, StreamRuntimeState.running}
                    else 0
                ),
                checkpoint_updated_at=normalize_optional_utc(
                    checkpoint.updated_at if checkpoint else None
                ),
                last_start_attempt_at=normalize_optional_utc(
                    checkpoint.last_start_attempt_at if checkpoint else None
                ),
                last_healthy_frame_at=normalize_optional_utc(
                    checkpoint.last_healthy_frame_at if checkpoint else None
                ),
                last_evidence_persisted_at=normalize_optional_utc(
                    checkpoint.last_evidence_persisted_at if checkpoint else None
                ),
                last_evidence_failure_at=normalize_optional_utc(
                    checkpoint.last_evidence_failure_at if checkpoint else None
                ),
                evidence_failure_code=(
                    checkpoint.evidence_failure_code if checkpoint else None
                ),
                last_clean_stop_at=normalize_optional_utc(
                    checkpoint.last_clean_stop_at if checkpoint else None
                ),
                last_failure_at=normalize_optional_utc(
                    checkpoint.last_failure_at if checkpoint else None
                ),
                failure_code=checkpoint.failure_code if checkpoint else None,
                consecutive_failure_count=(
                    checkpoint.consecutive_failure_count if checkpoint else 0
                ),
                next_retry_at=normalize_optional_utc(
                    checkpoint.next_retry_at if checkpoint else None
                ),
                last_stop_reason=checkpoint.last_stop_reason if checkpoint else "policy_off",
                safety_hold_active=(checkpoint.safety_hold_active if checkpoint else False),
                camera_start_requested=(
                    desired_mode == StreamMonitoringMode.armed
                    and actual_state
                    in {StreamRuntimeState.starting, StreamRuntimeState.running}
                ),
                monitor_start_requested=(actual_state == StreamRuntimeState.running),
                message=message,
                warnings=warnings,
            )

    def list_stream_monitoring_statuses(
        self,
        *,
        limit: int = 50,
    ) -> list[StreamRuntimeStatusResponse]:
        """Return a bounded, read-only status view for existing dashboard surfaces."""

        stream_ids = [stream.id for stream in self.list_streams()[:limit]]
        return [
            status
            for stream_id in stream_ids
            if (status := self.get_stream_runtime_status(stream_id)) is not None
        ]

    def set_stream_monitoring_enabled(
        self,
        stream_id: str,
        *,
        enabled: bool,
        idempotency_key: str,
    ) -> bool | None:
        """Persist explicit desired state once; callers wake the in-memory supervisor."""

        operation = "enable" if enabled else "disable"
        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                stream = session.get(StreamModel, stream_id)
                if stream is None:
                    return None
                existing = session.get(StreamMonitoringOperationModel, idempotency_key)
                if existing is not None:
                    if (
                        existing.stream_id != stream_id
                        or existing.operation != operation
                    ):
                        raise MonitoringOperationConflictError(
                            "monitoring_idempotency_key_conflict"
                        )
                    return True

                policy = session.get(StreamMonitoringPolicyModel, stream_id)
                checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
                if policy is None or checkpoint is None:
                    policy, checkpoint = _new_stream_monitoring_records(
                        stream_id,
                        created_at=now,
                    )
                    session.add_all((policy, checkpoint))
                    session.flush()

                requested_mode = (
                    StreamMonitoringMode.armed.value
                    if enabled
                    else StreamMonitoringMode.off.value
                )
                if policy.mode != requested_mode:
                    policy.mode = requested_mode
                    policy.policy_revision += 1
                    policy.updated_at = now
                    policy.armed_at = now if enabled else None
                    policy.paused_at = None
                    policy.pause_reason = None
                    checkpoint.observed_policy_revision = policy.policy_revision
                    checkpoint.actual_state = StreamRuntimeState.stopped.value
                    checkpoint.app_instance_id = None
                    checkpoint.runtime_generation_id = None
                    checkpoint.next_retry_at = None
                    checkpoint.failure_code = None
                    checkpoint.consecutive_failure_count = 0
                    checkpoint.safety_hold_active = False
                    checkpoint.last_stop_reason = (
                        "enabled" if enabled else "policy_disabled"
                    )
                    if not enabled:
                        checkpoint.last_clean_stop_at = now
                    checkpoint.updated_at = now

                session.add(
                    StreamMonitoringOperationModel(
                        idempotency_key=idempotency_key,
                        stream_id=stream_id,
                        operation=operation,
                        policy_revision=policy.policy_revision,
                        created_at=now,
                    )
                )
                self._sync_monitoring_alert(session, stream_id, now)
                return False

    def retry_stream_monitoring(
        self,
        stream_id: str,
        *,
        idempotency_key: str,
    ) -> bool | None:
        """Clear a bounded recovery hold only after an explicit retry request."""

        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                stream = session.get(StreamModel, stream_id)
                if stream is None:
                    return None
                existing = session.get(StreamMonitoringOperationModel, idempotency_key)
                if existing is not None:
                    if (
                        existing.stream_id != stream_id
                        or existing.operation != "retry"
                    ):
                        raise MonitoringOperationConflictError(
                            "monitoring_idempotency_key_conflict"
                        )
                    return True

                policy = session.get(StreamMonitoringPolicyModel, stream_id)
                checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
                if policy is None or policy.mode != StreamMonitoringMode.armed.value:
                    raise ValueError("monitoring_disabled")
                if checkpoint is None:
                    _, checkpoint = _new_stream_monitoring_records(
                        stream_id,
                        created_at=now,
                    )
                    session.add(checkpoint)

                if checkpoint.actual_state not in {
                    StreamRuntimeState.starting.value,
                    StreamRuntimeState.running.value,
                }:
                    checkpoint.actual_state = StreamRuntimeState.stopped.value
                    checkpoint.app_instance_id = None
                    checkpoint.runtime_generation_id = None
                    checkpoint.next_retry_at = now
                    checkpoint.failure_code = None
                    checkpoint.consecutive_failure_count = 0
                    checkpoint.safety_hold_active = False
                    checkpoint.last_stop_reason = "retry_requested"
                    checkpoint.updated_at = now

                session.add(
                    StreamMonitoringOperationModel(
                        idempotency_key=idempotency_key,
                        stream_id=stream_id,
                        operation="retry",
                        policy_revision=policy.policy_revision,
                        created_at=now,
                    )
                )
                self._sync_monitoring_alert(session, stream_id, now)
                return False

    def disable_stream_monitoring_for_manual_stop(self, stream_id: str) -> None:
        """Keep the legacy Stop camera control from being immediately restarted."""

        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                policy = session.get(StreamMonitoringPolicyModel, stream_id)
                checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
                if policy is None or checkpoint is None:
                    return
                if policy.mode != StreamMonitoringMode.off.value:
                    policy.mode = StreamMonitoringMode.off.value
                    policy.policy_revision += 1
                    policy.armed_at = None
                    policy.paused_at = None
                    policy.pause_reason = None
                    policy.updated_at = now
                checkpoint.observed_policy_revision = policy.policy_revision
                checkpoint.actual_state = StreamRuntimeState.stopped.value
                checkpoint.app_instance_id = None
                checkpoint.runtime_generation_id = None
                checkpoint.next_retry_at = None
                checkpoint.failure_code = None
                checkpoint.consecutive_failure_count = 0
                checkpoint.safety_hold_active = False
                checkpoint.last_clean_stop_at = now
                checkpoint.last_stop_reason = "manual_camera_stop"
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, stream_id, now)

    def prepare_for_supervision(self, app_instance_id: str) -> None:
        """Invalidate any process-owned checkpoint before a new app claims runtime."""

        now = datetime.now(UTC)
        nonterminal_states = {
            StreamRuntimeState.starting.value,
            StreamRuntimeState.running.value,
            StreamRuntimeState.backoff.value,
            StreamRuntimeState.stopping.value,
        }
        with self.session_factory() as session:
            with session.begin():
                checkpoints = session.scalars(
                    select(StreamRuntimeCheckpointModel).where(
                        StreamRuntimeCheckpointModel.actual_state.in_(nonterminal_states)
                    )
                ).all()
                for checkpoint in checkpoints:
                    checkpoint.actual_state = StreamRuntimeState.interrupted.value
                    checkpoint.app_instance_id = None
                    checkpoint.runtime_generation_id = None
                    checkpoint.last_stop_reason = "previous_process_ended"
                    checkpoint.updated_at = now
                    self._sync_monitoring_alert(session, checkpoint.stream_id, now)

    def list_enabled_monitoring_candidates(
        self,
        *,
        limit: int,
    ) -> list[DurableMonitoringCandidate]:
        """Read only explicit enabled intent; provider validation stays at start time."""

        bounded_limit = max(1, min(limit, 50))
        with self.session_factory() as session:
            rows = session.execute(
                select(StreamMonitoringPolicyModel, StreamRuntimeCheckpointModel)
                .join(
                    StreamRuntimeCheckpointModel,
                    StreamRuntimeCheckpointModel.stream_id
                    == StreamMonitoringPolicyModel.stream_id,
                )
                .where(
                    StreamMonitoringPolicyModel.mode == StreamMonitoringMode.armed.value
                )
                .order_by(StreamMonitoringPolicyModel.stream_id)
                .limit(bounded_limit)
            ).all()
            return [
                DurableMonitoringCandidate(
                    stream_id=policy.stream_id,
                    policy_revision=policy.policy_revision,
                    evaluation_interval_seconds=policy.evaluation_interval_seconds,
                    quiet_period_seconds=policy.quiet_period_seconds,
                    minimum_detection_count=policy.minimum_detection_count,
                    auto_create_review_candidates=(
                        policy.auto_create_review_candidates
                    ),
                    actual_state=checkpoint.actual_state,
                    consecutive_failure_count=checkpoint.consecutive_failure_count,
                    next_retry_at=normalize_optional_utc(checkpoint.next_retry_at),
                    last_start_attempt_at=normalize_optional_utc(
                        checkpoint.last_start_attempt_at
                    ),
                    safety_hold_active=checkpoint.safety_hold_active,
                    failure_code=checkpoint.failure_code,
                )
                for policy, checkpoint in rows
            ]

    def _checkpoint_for_enabled_candidate(
        self,
        session: Session,
        candidate: DurableMonitoringCandidate,
    ) -> StreamRuntimeCheckpointModel | None:
        policy = session.get(StreamMonitoringPolicyModel, candidate.stream_id)
        if (
            policy is None
            or policy.mode != StreamMonitoringMode.armed.value
            or policy.policy_revision != candidate.policy_revision
        ):
            return None
        return session.get(StreamRuntimeCheckpointModel, candidate.stream_id)

    def mark_monitoring_starting(
        self,
        candidate: DurableMonitoringCandidate,
        *,
        app_instance_id: str,
        now: datetime,
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                checkpoint = self._checkpoint_for_enabled_candidate(session, candidate)
                if checkpoint is None:
                    return
                if checkpoint.actual_state != StreamRuntimeState.starting.value:
                    checkpoint.start_count += 1
                    checkpoint.last_start_attempt_at = now
                    checkpoint.runtime_generation_id = uuid.uuid4().hex
                checkpoint.actual_state = StreamRuntimeState.starting.value
                checkpoint.observed_policy_revision = candidate.policy_revision
                checkpoint.app_instance_id = app_instance_id
                checkpoint.next_retry_at = None
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, candidate.stream_id, now)

    def mark_monitoring_running(
        self,
        candidate: DurableMonitoringCandidate,
        *,
        app_instance_id: str,
        healthy_at: datetime,
        now: datetime,
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                checkpoint = self._checkpoint_for_enabled_candidate(session, candidate)
                if checkpoint is None:
                    return
                last_frame_is_due = (
                    checkpoint.last_healthy_frame_at is None
                    or _as_utc(healthy_at) - _as_utc(checkpoint.last_healthy_frame_at)
                    >= CAMERA_HEALTH_CHECKPOINT_INTERVAL
                )
                changed = (
                    checkpoint.actual_state != StreamRuntimeState.running.value
                    or checkpoint.observed_policy_revision != candidate.policy_revision
                    or checkpoint.app_instance_id != app_instance_id
                    or checkpoint.next_retry_at is not None
                    or checkpoint.failure_code is not None
                    or checkpoint.consecutive_failure_count != 0
                    or checkpoint.safety_hold_active
                    or last_frame_is_due
                )
                if changed:
                    checkpoint.actual_state = StreamRuntimeState.running.value
                    checkpoint.observed_policy_revision = candidate.policy_revision
                    checkpoint.app_instance_id = app_instance_id
                    if last_frame_is_due:
                        checkpoint.last_healthy_frame_at = healthy_at
                    checkpoint.next_retry_at = None
                    checkpoint.failure_code = None
                    checkpoint.consecutive_failure_count = 0
                    checkpoint.safety_hold_active = False
                    checkpoint.updated_at = now
                self._sync_monitoring_alert(session, candidate.stream_id, now)

    def mark_monitoring_waiting(
        self,
        candidate: DurableMonitoringCandidate,
        *,
        now: datetime,
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                checkpoint = self._checkpoint_for_enabled_candidate(session, candidate)
                if checkpoint is None:
                    return
                if (
                    checkpoint.actual_state == StreamRuntimeState.blocked.value
                    and checkpoint.failure_code == "waiting_for_capacity"
                ):
                    self._sync_monitoring_alert(session, candidate.stream_id, now)
                    return
                checkpoint.actual_state = StreamRuntimeState.blocked.value
                checkpoint.observed_policy_revision = candidate.policy_revision
                checkpoint.failure_code = "waiting_for_capacity"
                checkpoint.next_retry_at = None
                checkpoint.last_stop_reason = "waiting_for_capacity"
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, candidate.stream_id, now)

    def mark_monitoring_backoff(
        self,
        candidate: DurableMonitoringCandidate,
        *,
        app_instance_id: str,
        failure_count: int,
        retry_at: datetime,
        now: datetime,
        failure_code: str = "camera_unavailable",
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                checkpoint = self._checkpoint_for_enabled_candidate(session, candidate)
                if checkpoint is None:
                    return
                if (
                    checkpoint.actual_state == StreamRuntimeState.backoff.value
                    and checkpoint.next_retry_at == retry_at
                    and checkpoint.consecutive_failure_count == failure_count
                    and checkpoint.failure_code == failure_code
                ):
                    return
                checkpoint.actual_state = StreamRuntimeState.backoff.value
                checkpoint.observed_policy_revision = candidate.policy_revision
                checkpoint.app_instance_id = app_instance_id
                checkpoint.last_failure_at = now
                checkpoint.failure_code = failure_code
                checkpoint.consecutive_failure_count = failure_count
                checkpoint.failure_count += 1
                checkpoint.next_retry_at = retry_at
                checkpoint.last_stop_reason = "runtime_unhealthy"
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, candidate.stream_id, now)

    def mark_monitoring_backoff_with_failure_code(
        self,
        candidate: DurableMonitoringCandidate,
        *,
        app_instance_id: str,
        failure_count: int,
        retry_at: datetime,
        failure_code: str,
        now: datetime,
    ) -> None:
        """Persist a small approved runtime code without retaining provider errors."""

        if failure_code not in CAMERA_NODE_RUNTIME_FAILURE_CODES:
            failure_code = "camera_unavailable"
        self.mark_monitoring_backoff(
            candidate,
            app_instance_id=app_instance_id,
            failure_count=failure_count,
            retry_at=retry_at,
            now=now,
            failure_code=failure_code,
        )

    def mark_monitoring_blocked(
        self,
        candidate: DurableMonitoringCandidate,
        *,
        app_instance_id: str,
        failure_count: int,
        failure_code: str,
        now: datetime,
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                checkpoint = self._checkpoint_for_enabled_candidate(session, candidate)
                if checkpoint is None:
                    return
                if (
                    checkpoint.actual_state == StreamRuntimeState.blocked.value
                    and checkpoint.failure_code == failure_code
                    and checkpoint.consecutive_failure_count == failure_count
                ):
                    return
                checkpoint.actual_state = StreamRuntimeState.blocked.value
                checkpoint.observed_policy_revision = candidate.policy_revision
                checkpoint.app_instance_id = app_instance_id
                checkpoint.last_failure_at = now
                checkpoint.failure_code = failure_code
                checkpoint.consecutive_failure_count = failure_count
                checkpoint.failure_count += 1
                checkpoint.next_retry_at = None
                checkpoint.last_stop_reason = failure_code
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, candidate.stream_id, now)

    def mark_monitoring_stopped(
        self,
        stream_id: str,
        *,
        reason: str,
        now: datetime,
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                policy = session.get(StreamMonitoringPolicyModel, stream_id)
                checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
                if checkpoint is None:
                    return
                checkpoint.actual_state = StreamRuntimeState.stopped.value
                checkpoint.observed_policy_revision = (
                    policy.policy_revision if policy is not None else 1
                )
                checkpoint.app_instance_id = None
                checkpoint.runtime_generation_id = None
                checkpoint.last_clean_stop_at = now
                checkpoint.next_retry_at = None
                checkpoint.last_stop_reason = reason
                checkpoint.updated_at = now
                self._sync_monitoring_alert(session, stream_id, now)

    def record_stream_health_observation(
        self,
        stream_id: str,
        *,
        last_evidence_persisted_at: datetime | None,
        evidence_persistence_failed: bool,
        now: datetime,
    ) -> None:
        """Store sparse lifecycle evidence results without retaining frames or errors.

        This is invoked by the existing supervisor only. It records transitions and
        periodic successes, never every frame or a raw provider exception.
        """

        with self.session_factory() as session:
            with session.begin():
                checkpoint = session.get(StreamRuntimeCheckpointModel, stream_id)
                policy = session.get(StreamMonitoringPolicyModel, stream_id)
                if checkpoint is None or policy is None:
                    return
                changed = False
                if evidence_persistence_failed:
                    if checkpoint.evidence_failure_code != "evidence_persistence_failed":
                        checkpoint.evidence_failure_code = "evidence_persistence_failed"
                        checkpoint.last_evidence_failure_at = now
                        changed = True
                elif (
                    last_evidence_persisted_at is not None
                    and (
                        checkpoint.last_evidence_persisted_at is None
                        or _as_utc(last_evidence_persisted_at)
                        - _as_utc(checkpoint.last_evidence_persisted_at)
                        >= CAMERA_HEALTH_CHECKPOINT_INTERVAL
                    )
                ):
                    checkpoint.last_evidence_persisted_at = last_evidence_persisted_at
                    checkpoint.evidence_failure_code = None
                    changed = True
                if changed:
                    checkpoint.updated_at = now
                    self._sync_monitoring_alert(session, stream_id, now)

    def get_stream_playback_status(self, stream_id: str) -> StreamPlaybackStatus | None:
        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None

            source = session.get(CameraSourceModel, stream.source_id)
            if source is None:
                return StreamPlaybackStatus(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    status=StreamPlaybackStatusValue.unavailable,
                    playback_kind=StreamPlaybackKind.placeholder,
                    display_title=stream.name,
                    message="The stream source is missing, so playback cannot be shown.",
                    setup_hint="Restore the source before connecting future playback adapters.",
                    supports_zone_editing=True,
                    supports_live_playback=False,
                )

            if source.status == SourceStatus.archived.value:
                return StreamPlaybackStatus(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    status=StreamPlaybackStatusValue.offline,
                    playback_kind=StreamPlaybackKind.placeholder,
                    display_title=stream.name,
                    message="This camera is archived, so its Stream is paused.",
                    setup_hint="Restore the camera from Cameras/Streams to use it again.",
                    supports_zone_editing=False,
                    supports_live_playback=False,
                    adapter_key=source.kind,
                )

            adapter_key = source.kind
            model = session.get(SourceProviderConfigurationModel, source.id)
            configured_provider_key = model.provider_key if model is not None else None
            if configured_provider_key == "folder_import_future":
                configuration = _source_provider_configuration_from_model(
                    source,
                    model,
                    [stream.id],
                )
                if configuration.missing_fields:
                    message = (
                        "This stream has folder/trail-cam provider metadata pending. "
                        "Playback remains placeholder/media-context only."
                    )
                    setup_hint = (
                        "Add folder path metadata before folder preview/import can run."
                    )
                else:
                    message = (
                        "Folder/trail-cam metadata is configured for future import context. "
                        "This stream does not provide live playback."
                    )
                    setup_hint = (
                        "Preview or import folder media from Source setup; imported media "
                        "remains MediaAsset context until a future evidence handoff."
                    )
                return StreamPlaybackStatus(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    status=StreamPlaybackStatusValue.not_configured,
                    playback_kind=StreamPlaybackKind.placeholder,
                    display_title=stream.name,
                    message=message,
                    setup_hint=setup_hint,
                    supports_zone_editing=True,
                    supports_live_playback=False,
                    adapter_key=configured_provider_key,
                )
            if configured_provider_key == "webhook_future":
                configuration = _source_provider_configuration_from_model(
                    source,
                    model,
                    [stream.id],
                )
                if configuration.missing_fields:
                    message = (
                        "This stream has webhook provider metadata pending. "
                        "Playback remains placeholder/media-context only."
                    )
                    setup_hint = (
                        "Add shared secret metadata before future webhook validation or "
                        "ingest can be implemented."
                    )
                else:
                    message = (
                        "Webhook metadata is configured for explicit motion-evidence context. "
                        "This stream does not provide live playback."
                    )
                    setup_hint = (
                        "Webhook motion metadata can create pending evidence through the "
                        "explicit endpoint, but playback and media ingest remain future work."
                    )
                return StreamPlaybackStatus(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    status=StreamPlaybackStatusValue.not_configured,
                    playback_kind=StreamPlaybackKind.placeholder,
                    display_title=stream.name,
                    message=message,
                    setup_hint=setup_hint,
                    supports_zone_editing=True,
                    supports_live_playback=False,
                    adapter_key=configured_provider_key,
                )
            if configured_provider_key == "camera_node":
                configuration = _source_provider_configuration_from_model(
                    source,
                    model,
                    [stream.id],
                )
                if not configuration.missing_fields and configuration.supports_live_playback:
                    return StreamPlaybackStatus(
                        stream_id=stream.id,
                        source_id=stream.source_id,
                        status=StreamPlaybackStatusValue.live_ready,
                        playback_kind=StreamPlaybackKind.camera_node,
                        display_title=stream.name,
                        message="Paired Camera Node is ready for an authenticated bounded snapshot preview.",
                        setup_hint="Opening preview does not enable monitoring or persist frames.",
                        supports_zone_editing=True,
                        supports_live_playback=True,
                        adapter_key="camera_node",
                        bridged_mjpeg_url=f"/api/streams/{stream.id}/live/mjpeg",
                        live_stream_type="camera_node",
                    )
                return StreamPlaybackStatus(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    status=StreamPlaybackStatusValue.not_configured,
                    playback_kind=StreamPlaybackKind.camera_node,
                    display_title=stream.name,
                    message="Camera Node pairing is required before preview or monitoring can run.",
                    setup_hint="Pair or repair the Camera Node from Edit camera setup.",
                    supports_zone_editing=True,
                    supports_live_playback=False,
                    adapter_key="camera_node",
                    live_stream_type="camera_node",
                )
            if configured_provider_key == "local_usb":
                config = json.loads(model.config_json) if model is not None else {}
                live_type = _normalize_live_stream_type(config.get("live_stream_type"), "")
                if live_type == windows_camera_bridge.WINDOWS_DSHOW_STREAM_TYPE:
                    return _windows_dshow_stream_playback_status(
                        stream=stream,
                        config=config,
                    )
                return _local_usb_stream_playback_status(
                    stream=stream,
                    config=config,
                )
            if configured_provider_key == "external_url":
                config = json.loads(model.config_json) if model is not None else {}
                return _external_url_stream_playback_status(
                    stream=stream,
                    config=config,
                )

            if source.kind == SourceKind.demo.value:
                return StreamPlaybackStatus(
                    stream_id=stream.id,
                    source_id=stream.source_id,
                    status=StreamPlaybackStatusValue.demo,
                    playback_kind=StreamPlaybackKind.demo_panel,
                    display_title=stream.name,
                    message=(
                        "This stream uses the local demo panel; no real video playback "
                        "is connected yet."
                    ),
                    setup_hint=(
                        "Future source adapters will feed this contract while zone editing "
                        "continues to work here."
                    ),
                    supports_zone_editing=True,
                    supports_live_playback=False,
                    adapter_key=adapter_key,
                )

            if source.status == SourceStatus.disconnected.value:
                status = StreamPlaybackStatusValue.offline
                message = "The source is disconnected, so MockingBird can show only a placeholder."
                setup_hint = "Reconnect or configure a future source adapter to enable playback."
            elif source.status == SourceStatus.needs_setup.value:
                status = StreamPlaybackStatusValue.not_configured
                message = "This stream needs source setup before playback can be shown."
                setup_hint = "Complete source setup later; zones can still be prepared now."
            else:
                status = StreamPlaybackStatusValue.not_configured
                message = "This stream has product metadata but no playback adapter configured yet."
                setup_hint = (
                    "A future source adapter can feed playback here without changing review "
                    "or zone workflows."
                )

            return StreamPlaybackStatus(
                stream_id=stream.id,
                source_id=stream.source_id,
                status=status,
                playback_kind=StreamPlaybackKind.placeholder,
                display_title=stream.name,
                message=message,
                setup_hint=setup_hint,
                supports_zone_editing=True,
                supports_live_playback=False,
                adapter_key=adapter_key,
            )

    def get_stream_live_playback_config(
        self,
        stream_id: str,
    ) -> StreamLivePlaybackConfig | None:
        with self.session_factory() as session:
            stream = session.get(StreamModel, stream_id)
            if stream is None:
                return None

            model = session.get(SourceProviderConfigurationModel, stream.source_id)
            provider_key = model.provider_key if model is not None else None
            config = json.loads(model.config_json) if model is not None else {}
            live_url = (config.get("live_stream_url") or "").strip() or None
            live_type = _normalize_live_stream_type(
                config.get("live_stream_type"),
                live_url or "",
            )
            if provider_key == "camera_node":
                live_type = "camera_node"
            video_size = (config.get("video_size") or "").strip() or None
            preview_video_size = (config.get("preview_video_size") or "").strip() or None
            capture_video_size = (config.get("capture_video_size") or "").strip() or None
            framerate = (config.get("framerate") or "").strip() or None
            input_format = (config.get("input_format") or "").strip() or None
            if (
                provider_key == "local_usb"
                and live_type != windows_camera_bridge.WINDOWS_DSHOW_STREAM_TYPE
            ):
                live_type = local_camera_bridge.LOCAL_USB_STREAM_TYPE
            return StreamLivePlaybackConfig(
                stream_id=stream.id,
                source_id=stream.source_id,
                provider_key=provider_key,
                live_stream_url=live_url,
                live_stream_type=live_type,
                local_camera_device=(
                    (config.get("local_camera_device") or "").strip() or None
                ),
                local_camera_format=(
                    local_camera_bridge.normalize_local_camera_format(
                        config.get("local_camera_format")
                    )
                ),
                windows_camera_name=(
                    (config.get("windows_camera_name") or "").strip() or None
                ),
                windows_ffmpeg_binary_path=(
                    (config.get("ffmpeg_binary_path") or "").strip() or None
                ),
                windows_video_size=preview_video_size or video_size,
                windows_framerate=framerate,
                camera_video_size=capture_video_size or video_size,
                camera_framerate=framerate,
                input_format=input_format,
                preview_video_size=preview_video_size,
                capture_video_size=capture_video_size,
                brightness=(config.get("brightness") or "").strip() or None,
                contrast=(config.get("contrast") or "").strip() or None,
                exposure=(config.get("exposure") or "").strip() or None,
                zoom_mode=(config.get("zoom_mode") or "").strip() or None,
                camera_node_base_address=(config.get("node_base_address") or "").strip() or None,
                camera_node_credential=(config.get("node_credential") or "").strip() or None,
                camera_node_camera_id=(config.get("node_camera_id") or "").strip() or None,
                camera_node_id=(config.get("node_id") or "").strip() or None,
                camera_node_monitoring_profile_id=(
                    (config.get("node_monitoring_profile_id") or "").strip() or None
                ),
                camera_node_evidence_profile_id=(
                    (config.get("node_evidence_profile_id") or "").strip() or None
                ),
            )

    def streams_for_source(self, source_id: str) -> list[Stream]:
        with self.session_factory() as session:
            streams = session.scalars(
                select(StreamModel)
                .where(StreamModel.source_id == source_id)
                .order_by(StreamModel.id)
            ).all()
            return [_stream_from_model(stream) for stream in streams]

    def _stream_ids_for_source(self, session: Session, source_id: str) -> list[str]:
        return [
            stream.id
            for stream in session.scalars(
                select(StreamModel).where(StreamModel.source_id == source_id).order_by(StreamModel.id)
            ).all()
        ]

    def list_zones(self) -> list[Zone]:
        with self.session_factory() as session:
            zones = session.scalars(select(ZoneModel).order_by(ZoneModel.id)).all()
            return [_zone_from_model(zone) for zone in zones]

    def get_zone(self, zone_id: str) -> Zone | None:
        with self.session_factory() as session:
            zone = session.get(ZoneModel, zone_id)
            return _zone_from_model(zone) if zone else None

    def zones_for_stream(self, stream_id: str) -> list[Zone]:
        with self.session_factory() as session:
            return self._zones_for_stream(session, stream_id)

    def create_zone(self, payload: ZoneCreate) -> Zone:
        with self.session_factory() as session:
            with session.begin():
                zone = ZoneModel(
                    id=self._next_id(session, ZoneModel, "zone"),
                    stream_id=payload.stream_id,
                    name=payload.name,
                    zone_type=payload.zone_type.value,
                    polygon_json=_points_to_json(payload.polygon),
                    is_active=payload.is_active,
                )
                session.add(zone)
                session.flush()
                return _zone_from_model(zone)

    def update_zone(self, zone_id: str, payload: ZoneUpdate) -> Zone | None:
        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None

                if payload.name is not None:
                    zone.name = payload.name
                if payload.zone_type is not None:
                    zone.zone_type = payload.zone_type.value
                if payload.polygon is not None:
                    zone.polygon_json = _points_to_json(payload.polygon)
                if payload.is_active is not None:
                    zone.is_active = payload.is_active

                session.flush()
                return _zone_from_model(zone)

    def update_zone_monitoring_policy(
        self,
        zone_id: str,
        payload: ZoneMonitoringPolicyUpdate,
    ) -> Zone | None:
        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None
                if ZoneType(zone.zone_type) in {ZoneType.privacy, ZoneType.ignore}:
                    raise ValueError("restricted_zone_monitoring_policy")

                overrides = _zone_monitoring_policy_overrides(zone.monitoring_policy_json)
                overrides.update(payload.model_dump(exclude_none=True, mode="json"))
                zone.monitoring_policy_json = json.dumps(overrides, sort_keys=True)
                session.flush()
                return _zone_from_model(zone)

    def restore_zone_monitoring_policy_defaults(self, zone_id: str) -> Zone | None:
        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None
                if ZoneType(zone.zone_type) in {ZoneType.privacy, ZoneType.ignore}:
                    raise ValueError("restricted_zone_monitoring_policy")
                zone.monitoring_policy_json = None
                session.flush()
                return _zone_from_model(zone)

    def delete_zone(self, zone_id: str) -> tuple[Zone, list[Zone]] | None:
        """Delete only an unreferenced Zone; linked review/evidence context is protected."""

        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None

                linked_counts = (
                    session.scalar(
                        select(func.count(EventModel.id)).where(
                            EventModel.primary_zone_id == zone_id
                        )
                    )
                    or 0,
                    session.scalar(
                        select(func.count(DetectionModel.id)).where(
                            DetectionModel.zone_id == zone_id
                        )
                    )
                    or 0,
                    session.scalar(
                        select(func.count(MotionEvidenceModel.id)).where(
                            MotionEvidenceModel.zone_id == zone_id
                        )
                    )
                    or 0,
                    session.scalar(
                        select(func.count(DetectionProposalModel.id)).where(
                            DetectionProposalModel.zone_id == zone_id
                        )
                    )
                    or 0,
                )
                referenced_by_provider = any(
                    json.loads(configuration.config_json).get("default_zone_id") == zone_id
                    for configuration in session.scalars(
                        select(SourceProviderConfigurationModel)
                    ).all()
                )
                if any(linked_counts) or referenced_by_provider:
                    raise ValueError("zone_has_review_context")

                deleted_zone = _zone_from_model(zone)
                stream_id = zone.stream_id
                session.delete(zone)
                session.flush()
                return deleted_zone, self._zones_for_stream(session, stream_id)

