def _motion_evidence_bulk_failure_message(reason: str) -> str:
    if reason == "motion_evidence_zone_blocked":
        return "Motion Evidence in privacy or ignore zones cannot be promoted."
    if reason == "missing_zone":
        return "Motion Evidence zone was not found."
    if reason == "missing_stream":
        return "Motion Evidence stream was not found."
    if reason == "missing_media_asset":
        return "Motion Evidence snapshot media was not found."
    if reason == "media_stream_mismatch":
        return "Motion evidence snapshot media must belong to the selected stream."
    return "Motion Evidence could not be processed."


def _review_queue_bulk_correction_failure_message(reason: str) -> str:
    if reason == "missing_visit":
        return "Visit was not found."
    if reason == "missing_event":
        return "Event was not found."
    if reason == "unsupported_target":
        return "Review target type is not supported."
    return "Review Queue item could not be corrected."


def _review_queue_timestamp(value: datetime) -> float:
    """Normalize persisted SQLite datetimes for deterministic newest-first review."""

    return normalize_utc(value).timestamp()


def _latest_review_label_model_id(labels: list[ReviewLabelModel]) -> str:
    latest = max(labels, key=lambda label: (label.created_at, label.id), default=None)
    return latest.id if latest is not None else ""


def _review_state_token_value(
    target_type: str,
    target_id: str,
    review_status: str,
    reviewed_label: str | None,
    latest_review_label_id: str,
    curation_state: str = "",
) -> str:
    state = "|".join(
        (
            target_type,
            target_id,
            review_status,
            reviewed_label or "",
            latest_review_label_id,
            curation_state,
        )
    )
    return hashlib.sha256(state.encode("utf-8")).hexdigest()[:24]


def _json_object(value: str | None) -> dict[str, Any]:
    try:
        parsed = json.loads(value or "{}")
    except (TypeError, ValueError):
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _json_list(value: str | None) -> list[dict[str, Any]]:
    try:
        parsed = json.loads(value or "[]")
    except (TypeError, ValueError):
        return []
    return [item for item in parsed if isinstance(item, dict)] if isinstance(parsed, list) else []


def _parse_datetime(value: Any) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return None
    return _as_utc(parsed)


def _json_string_list(value: str | None) -> list[str]:
    try:
        parsed = json.loads(value or "[]")
    except (TypeError, ValueError):
        return []
    return [item for item in parsed if isinstance(item, str)] if isinstance(parsed, list) else []


